def compute_event_id(operation_id: str | uuid.UUID, transaction_sequence: int, ref_name: str) -> str:
    """Matches src/events.rs::event_id deterministic SHA-256."""
    op_uuid = uuid.UUID(str(operation_id))
    h = hashlib.sha256()
    h.update(b"rootyard-ref-event-v1\0")
    h.update(op_uuid.bytes)
    h.update(int(transaction_sequence).to_bytes(8, "big", signed=True))
    h.update(ref_name.encode("utf-8"))
    return h.hexdigest()


def valid_oid(oid: Any, length: int = 40) -> bool:
    if not isinstance(oid, str) or len(oid) != length:
        return False
    return all(c in "0123456789abcdef" for c in oid)


def valid_non_zero_oid(oid: Any, length: int = 40) -> bool:
    return valid_oid(oid, length) and oid != ("0" * length)


def valid_single_line_text(value: Any, max_bytes: int) -> bool:
    if not isinstance(value, str):
        return False
    trimmed = value.strip()
    if not trimmed:
        return False
    raw = value.encode("utf-8")
    if len(raw) > max_bytes:
        return False
    for b in raw:
        if b < 0x20 or b == 0x7F:
            return False
    return True


def valid_multiline_text(value: Any, max_bytes: int) -> bool:
    if not isinstance(value, str):
        return False
    raw = value.encode("utf-8")
    if len(raw) > max_bytes:
        return False
    for b in raw:
        if (b < 0x20 and b not in (0x09, 0x0A, 0x0D)) or b == 0x7F:
            return False
    return True


def valid_idempotency_key(key: Optional[str]) -> bool:
    if key is None:
        return True
    if not isinstance(key, str) or not (1 <= len(key) <= 128):
        return False
    return all(c.isalnum() or c in "._:-" for c in key)


def find_migration_sql(filename: str, staged_relpath: str) -> Optional[Path]:
    """Locates migration SQL in migrations/ (M5) or staged in src/<domain>/ (M1-M4)."""
    promoted = ROOT / "migrations" / filename
    if promoted.is_file():
        return promoted
    staged = ROOT / staged_relpath
    if staged.is_file():
        return staged
    return None


def get_track_migration_sql(candidate_relpaths: Iterable[str], fallback_sql: str) -> tuple[str, Optional[Path]]:
    """Locates a Tier-2 staged or promoted SQL file across candidate paths or returns fallback_sql."""
    for rel in candidate_relpaths:
        p = ROOT / rel
        if p.is_file():
            return p.read_text(encoding="utf-8"), p
    if os.environ.get("ROOTYARD_E2E_REQUIRE_M11") == "1":
        raise AssertionError(f"Missing required Tier-2 migration file among {list(candidate_relpaths)}")
    return fallback_sql, None


