class TestTier1FeatureCoverage(BaseRootyardTestCase):
    """Tier 1: Feature Coverage (155 tests = 5 per feature F1-F31)."""


    # =========================================================================
    # Feature F1: PR State Machine & CRUD (5 Tests)
    # =========================================================================
    def test_t1_f01_01_create_pull_resolves_git_refs_and_allocates_monotonic_number(self) -> None:
        git_fx, pulls = self.make_pulls_rig()
        st1, pr1 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Add feature", "refs/heads/feature", "refs/heads/main", body="Initial PR")
        st2, pr2 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Second PR", "refs/heads/diverged", "refs/heads/main")
        self.assertEqual(st1, 201)
        self.assertEqual(st2, 201)
        self.assertEqual(pr1["number"], 1)
        self.assertEqual(pr2["number"], 2)
        self.assertEqual(pr1["state"], "open")
        self.assertEqual(pr1["version"], 1)
        self.assertEqual(pr1["head_oid"], git_fx.resolve_ref("refs/heads/feature"))
        self.assertEqual(pr1["base_oid"], git_fx.resolve_ref("refs/heads/main"))
        self.assertIsNone(pr1["merge_commit_oid"])
        counter_row = pulls.conn.execute("SELECT next_number FROM forge_pull_counters WHERE repository_id=?", (DEFAULT_REPO_ID,)).fetchone()
        self.assertEqual(int(counter_row["next_number"]), 3)

    def test_t1_f01_02_get_pull_and_list_pulls_keyset_pagination(self) -> None:
        _, pulls = self.make_pulls_rig()
        for i in range(1, 6):
            st, _ = pulls.create_pull(ALICE, DEFAULT_REPO_ID, f"PR {i}", "refs/heads/feature", "refs/heads/main")
            self.assertEqual(st, 201)
        s1, p1 = pulls.list_pulls(ALICE, DEFAULT_REPO_ID, after=0, limit=2)
        s2, p2 = pulls.list_pulls(ALICE, DEFAULT_REPO_ID, after=p1["next_after"], limit=2)
        s3, p3 = pulls.list_pulls(ALICE, DEFAULT_REPO_ID, after=p2["next_after"], limit=2)
        self.assertEqual((s1, s2, s3), (200, 200, 200))
        self.assertEqual([x["number"] for x in p1["items"]], [1, 2])
        self.assertEqual(p1["next_after"], 2)
        self.assertEqual([x["number"] for x in p2["items"]], [3, 4])
        self.assertEqual(p2["next_after"], 4)
        self.assertEqual([x["number"] for x in p3["items"]], [5])
        self.assertIsNone(p3["next_after"])
        sg, item3 = pulls.get_pull(ALICE, DEFAULT_REPO_ID, 3)
        self.assertEqual(sg, 200)
        self.assertEqual(item3["title"], "PR 3")
        self.assertEqual(item3["cache_control"], "no-store")

    def test_t1_f01_03_list_pulls_state_filter_open_closed_merged(self) -> None:
        _, pulls = self.make_pulls_rig()
        _, pr1 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Open PR", "refs/heads/feature", "refs/heads/main")
        _, pr2 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Closed PR", "refs/heads/feature", "refs/heads/main")
        _, pr3 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Merged PR", "refs/heads/feature", "refs/heads/main")
        pulls.patch_pull(ALICE, DEFAULT_REPO_ID, pr2["number"], expected_version=1, state="closed")
        st_m, _ = pulls.merge_pull(ALICE, DEFAULT_REPO_ID, pr3["number"], 1, pr3["head_oid"], pr3["base_oid"])
        self.assertEqual(st_m, 200)
        _, open_list = pulls.list_pulls(ALICE, DEFAULT_REPO_ID, state="open")
        _, closed_list = pulls.list_pulls(ALICE, DEFAULT_REPO_ID, state="closed")
        _, merged_list = pulls.list_pulls(ALICE, DEFAULT_REPO_ID, state="merged")
        self.assertEqual([p["number"] for p in open_list["items"]], [1])
        self.assertEqual([p["number"] for p in closed_list["items"]], [2])
        self.assertEqual([p["number"] for p in merged_list["items"]], [3])

