    def test_t1_f01_05_patch_open_pull_refresh_head_oid_and_idempotent_create_replay(self) -> None:
        git_fx, pulls = self.make_pulls_rig()
        st_a, pr_a = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Idempotent PR", "refs/heads/feature", "refs/heads/main", idempotency_key="pr-create-key-1")
        st_b, pr_b = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Idempotent PR", "refs/heads/feature", "refs/heads/main", idempotency_key="pr-create-key-1")
        self.assertEqual((st_a, st_b), (201, 201))
        self.assertEqual(pr_a["number"], pr_b["number"])
        new_tree = git_fx.write_tree({"README.md": ("100644", b"# Rootyard\nNew head commit.\n")})
        new_head_oid = git_fx.commit_tree(new_tree, [pr_a["head_oid"]], "Advance feature head")
        git_fx.update_ref("refs/heads/feature", new_head_oid)
        st_p, pr_upd = pulls.patch_pull(ALICE, DEFAULT_REPO_ID, pr_a["number"], expected_version=1, head_oid=new_head_oid)
        self.assertEqual(st_p, 200)
        self.assertEqual(pr_upd["head_oid"], new_head_oid)
