    def test_t1_f06_02_merge_commit_strategy_creates_two_parent_commit_without_worktree(self) -> None:
        git_fx, pulls = self.make_pulls_rig()
        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "refs/heads/main", require_fast_forward=False)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Diverged merge", "refs/heads/diverged", "refs/heads/main")
        st, merged = pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 1, 1, pr["head_oid"], pr["base_oid"], strategy="merge_commit")
        self.assertEqual(st, 200)
        mc_oid = merged["merge_commit_oid"]
        self.assertNotEqual(mc_oid, pr["head_oid"])
        self.assertEqual(git_fx.resolve_ref("refs/heads/main"), mc_oid)
        commit_raw = git_fx.cat_file_bytes(mc_oid, "commit").decode("utf-8")
        self.assertIn(f"parent {pr['base_oid']}", commit_raw)
        self.assertIn(f"parent {pr['head_oid']}", commit_raw)

