    def test_t1_f11_01_batch_upload_new_object_returns_upload_and_verify_actions(self) -> None:
        lfs = self.make_lfs_rig()
        oid = hashlib.sha256(b"hello lfs").hexdigest()
        st, body, hdrs = lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": oid, "size": 9}])
        self.assertEqual(st, 200)
        self.assertEqual(hdrs["Content-Type"], "application/vnd.git-lfs+json")
        self.assertEqual(hdrs["Cache-Control"], "no-store")
        self.assertEqual(body["transfer"], "basic")
        obj = body["objects"][0]
        self.assertIn("upload", obj["actions"])
        self.assertIn("verify", obj["actions"])

    def test_t1_f11_02_batch_upload_existing_ready_object_omits_actions_deduplication(self) -> None:
        lfs = self.make_lfs_rig()
        payload = b"dedup lfs payload"
        oid = hashlib.sha256(payload).hexdigest()
        lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": oid, "size": len(payload)}])
        lfs.put_object(ALICE, DEFAULT_REPO_ID, oid, len(payload), [payload])
        st, body, _ = lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": oid, "size": len(payload)}])
        self.assertEqual(st, 200)
        self.assertNotIn("actions", body["objects"][0])

