    def test_t1_f12_04_streaming_get_download_returns_exact_bytes_and_security_headers(self) -> None:
        lfs = self.make_lfs_rig()
        payload = b"\x00\x01\x02binary-lfs-stream\xff"
        oid = hashlib.sha256(payload).hexdigest()
