    # Feature F13: CI Mirror Disk Watermark & Safe LRU Eviction (5 Tests)
    # =========================================================================
    def test_t1_f13_01_lru_eviction_reclaims_unreferenced_snapshots_and_pins(self) -> None:
        mfx = MirrorPinCheckoutFixture(self.tmp_path / "m_f13_01")
        c1, c2 = mfx.git.commits["c1"], mfx.git.commits["c2"]
        mfx.sync_mirror_snapshot("snap_1", mtime=1000.0)
        mfx.materialize_mirror_pin_and_job_view("snap_1", c1, create_job_view=False, mtime=1000.0)
        mfx.sync_mirror_snapshot("snap_2", mtime=2000.0)
        mfx.materialize_mirror_pin_and_job_view("snap_2", c2, create_job_view=False, mtime=2000.0)
        mfx.sync_mirror_snapshot("snap_3", mtime=3000.0)
        keep_bytes = mfx._dir_bytes(mfx.mirror_repo_dir / "snap_2") + mfx._dir_bytes(mfx.mirror_repo_dir / "snap_3") + 1024
        st, ev = mfx.evict_mirror(max_bytes=keep_bytes)
        self.assertEqual(st, 200)
        self.assertEqual(ev["evicted_pins"], 1)
        self.assertEqual(ev["evicted_snapshots"], 1)
        self.assertGreater(ev["reclaimed_bytes"], 0)
        self.assertFalse((mfx.mirror_repo_dir / "snap_1").exists())
        self.assertTrue((mfx.mirror_repo_dir / "snap_2").exists())
        self.assertTrue((mfx.mirror_repo_dir / "snap_3").exists())

