    # =========================================================================
    # Feature F16: Pando Streaming Delta Resolution & Graph Traversal (5 Tests)
    # =========================================================================
    def test_t1_f16_01_streaming_pack_parser_and_ofs_delta_chain_resolution(self) -> None:
        git_fx = self.clone_git_fixture("pando_f16_01.git")
        base_text = ("line-0123456789abcdef\n" * 400).encode("utf-8")
        parent = git_fx.commits["c2"]
        for i in range(4):
            b_oid = git_fx.write_blob(base_text + f"edit-{i}\n".encode("utf-8"))
            t_oid = git_fx.write_tree({"big.txt": ("100644", b_oid)})
            parent = git_fx.commit_tree(t_oid, [parent], f"Delta commit {i}")
        git_fx.update_ref("refs/heads/delta", parent)
        pack_res = git_fx.run_git(["pack-objects", "--stdout", "--revs", "--delta-base-offset", "--window=10", "--depth=10"], input_bytes=f"{parent}\n".encode("ascii"))
        parsed = PandoDeltaGraphExportFixture.parse_and_resolve_pack(pack_res.stdout)
        self.assertTrue(parsed["verified"])
        self.assertIn(6, parsed["raw_types"])  # OBJ_OFS_DELTA present
        self.assertIn(parent, parsed["objects"])

    def test_t1_f16_02_streaming_ref_delta_resolution_and_trailer_sha1_verification(self) -> None:
        git_fx = self.clone_git_fixture("pando_f16_02.git")
        base_text = ("ref-delta-content-block-\n" * 400).encode("utf-8")
        parent = git_fx.commits["c2"]
        for i in range(3):
            b_oid = git_fx.write_blob(base_text + f"ref-step-{i}\n".encode("utf-8"))
            t_oid = git_fx.write_tree({"refbig.txt": ("100644", b_oid)})
            parent = git_fx.commit_tree(t_oid, [parent], f"Ref delta {i}")
        pack_res = git_fx.run_git(["pack-objects", "--stdout", "--revs", "--window=10", "--depth=10"], input_bytes=f"{parent}\n".encode("ascii"))
        parsed = PandoDeltaGraphExportFixture.parse_and_resolve_pack(pack_res.stdout)
        self.assertTrue(parsed["verified"])
        self.assertIn(7, parsed["raw_types"])  # OBJ_REF_DELTA present
        self.assertEqual(hashlib.sha1(pack_res.stdout[:-20]).digest(), pack_res.stdout[-20:])

    def test_t1_f16_03_commit_and_tree_dag_walker_full_reachable_closure(self) -> None:
        git_fx = self.clone_git_fixture("pando_f16_03.git")
