    # =========================================================================
    # Feature F22: Track A — Webhook Subscriptions, HMAC-SHA256 & Outbox Delivery (5 Tests)
    # =========================================================================
    def test_t1_f22_01_webhook_crud_lifecycle_secret_masking_and_cas_versioning(self) -> None:
        _, _, webhooks, _ = self.make_webhooks_rig()
        secret = "super-secret-hmac-key-01"
        st_c, hk = webhooks.create_webhook(
            ALICE,
            DEFAULT_REPO_ID,
            "http://127.0.0.1:9999/hook",
            secret,
            events=["push", "pull_request", "check_run"],
            ci_contexts=["ci/build", "ci/lint"],
            idempotency_key="wh-create-1",
        )
        self.assertEqual(st_c, 201)
        self.assertTrue(hk["has_secret"])
        self.assertNotIn("secret", hk)
        self.assertEqual(hk["secret_sha256"], hashlib.sha256(secret.encode("utf-8")).hexdigest())
        self.assertEqual(hk["version"], 1)
        # Idempotent replay
        st_r, hk_r = webhooks.create_webhook(
            ALICE,
            DEFAULT_REPO_ID,
            "http://127.0.0.1:9999/hook",
            secret,
            events=["push", "pull_request", "check_run"],
            ci_contexts=["ci/build", "ci/lint"],
            idempotency_key="wh-create-1",
        )
        self.assertEqual((st_r, hk_r["id"]), (201, hk["id"]))
        # Patch with expected_version=1
        st_p, hk_p = webhooks.patch_webhook(ALICE, DEFAULT_REPO_ID, hk["id"], expected_version=1, active=False)
        self.assertEqual((st_p, hk_p["version"], hk_p["active"]), (200, 2, False))
        self.assertEqual(webhooks.delete_webhook(ALICE, DEFAULT_REPO_ID, hk["id"])[0], 200)
        self.assertEqual(webhooks.get_webhook(ALICE, DEFAULT_REPO_ID, hk["id"])[0], 404)

    def test_t1_f22_02_rfc2104_hmac_sha256_signing_and_real_loopback_http_delivery(self) -> None:
        _, _, webhooks, _ = self.make_webhooks_rig()
        secret = "loopback-hmac-secret-99"
        with LoopbackWebhookReceiver(response_codes=[200], secret=secret) as rx:
            _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, rx.url, secret, events=["ping", "push"])
            st_ping, ping_deliv = webhooks.ping_webhook(ALICE, DEFAULT_REPO_ID, hk["id"])
            self.assertEqual((st_ping, ping_deliv["state"]), (201, "pending"))
            st_disp, disp = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1000)
            self.assertEqual((st_disp, disp["dispatched"]), (200, 1))
            self.assertEqual(disp["items"][0]["state"], "delivered")
            self.assertEqual(disp["items"][0]["response_status"], 200)
            self.assertEqual(len(rx.received), 1)
            self.assertTrue(rx.received[0]["signature_valid"])
            self.assertEqual(rx.received[0]["headers"]["X-Rootyard-Event"], "ping")

    def test_t1_f22_03_outbox_event_fanout_and_event_id_deduplication(self) -> None:
        git_fx, pulls, webhooks, _ = self.make_webhooks_rig()
        browse = Track2BrowseEngine(git_fx, pulls)
        _, hk1 = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9001/h1", "secret-key-one", events=["push"])
        _, hk2 = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9002/h2", "secret-key-two", events=["pull_request"])
        browse.post_ref_transaction(
            ALICE,
            DEFAULT_REPO_ID,
            1,
            [{"ref_name": "refs/heads/main", "old_oid": git_fx.commits["c2"], "new_oid": git_fx.commits["c3"]}],
        )
        enq1 = webhooks.sync_outbox_events()
        enq2 = webhooks.sync_outbox_events()
        self.assertEqual((enq1, enq2), (1, 0))
        self.assertEqual(len(webhooks.list_deliveries(ALICE, DEFAULT_REPO_ID, hk1["id"])[1]["items"]), 1)
        self.assertEqual(len(webhooks.list_deliveries(ALICE, DEFAULT_REPO_ID, hk2["id"])[1]["items"]), 0)

    def test_t1_f22_04_exponential_backoff_retry_progression_and_manual_dead_letter_recovery(self) -> None:
        _, _, webhooks, _ = self.make_webhooks_rig()
        secret = "retry-backoff-secret-123"
        with LoopbackWebhookReceiver(response_codes=[502, 503, 500, 200], secret=secret) as rx:
            _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, rx.url, secret, events=["ping"])
            _, deliv = webhooks.ping_webhook(ALICE, DEFAULT_REPO_ID, hk["id"], max_attempts=3)
            # Attempt 1 @ t=1000 -> 502 -> failed, next_attempt_unix=1002
            _, d1 = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1000, base_backoff_sec=2)
            self.assertEqual((d1["items"][0]["state"], d1["items"][0]["attempts"], d1["items"][0]["next_attempt_unix"]), ("failed", 1, 1002))
            # Attempt 2 @ t=1002 -> 503 -> failed, next_attempt_unix=1006
            _, d2 = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1002, base_backoff_sec=2)
            self.assertEqual((d2["items"][0]["state"], d2["items"][0]["attempts"], d2["items"][0]["next_attempt_unix"]), ("failed", 2, 1006))
            # Attempt 3 @ t=1006 -> 500 -> dead_letter
            _, d3 = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1006, base_backoff_sec=2)
            self.assertEqual((d3["items"][0]["state"], d3["items"][0]["attempts"]), ("dead_letter", 3))
            # Manual retry resets to pending and succeeds on Attempt 4 (200)
            st_rt, rt = webhooks.retry_delivery(ALICE, DEFAULT_REPO_ID, hk["id"], deliv["id"], now_unix=1010)
            self.assertEqual((st_rt, rt["state"]), (200, "pending"))
            _, d4 = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1010)
            self.assertEqual((d4["items"][0]["state"], d4["items"][0]["attempts"], d4["items"][0]["response_status"]), ("delivered", 4, 200))

