        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_checks=["ci/unit", "ci/lint"])
        webhooks.create_webhook(
            ALICE,
            DEFAULT_REPO_ID,
            "http://127.0.0.1:9100/ci",
            "ci-orchestration-secret",
            events=["pull_request"],
            ci_contexts=["ci/sec"],
        )
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Auto CI PR", "refs/heads/feature", "refs/heads/main")
        orch = webhooks.on_pull_synchronized(ALICE, DEFAULT_REPO_ID, pr, action="opened")
        self.assertTrue(orch["pin_created"])
        self.assertEqual(orch["seeded_checks"], ["ci/lint", "ci/sec", "ci/unit"])
        self.assertEqual(orch["deliveries_enqueued"], 1)
        self.assertEqual(mfx.git.resolve_ref(orch["retention_ref"]), pr["head_oid"])
        _, checks = pulls.list_checks_for_pull(ALICE_RO, DEFAULT_REPO_ID, pr["number"])
        self.assertEqual([(c["context"], c["status"]) for c in checks["items"]], [("ci/lint", "queued"), ("ci/sec", "queued"), ("ci/unit", "queued")])

