    def test_t1_f23_03_signed_ci_webhook_callback_transitions_check_runs_to_in_progress_and_completed(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "callback-hmac-secret-key"
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9102/ci", secret, events=["pull_request"], ci_contexts=["ci/e2e"])
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Callback PR", "refs/heads/feature", "refs/heads/main")
        webhooks.on_pull_synchronized(ALICE, DEFAULT_REPO_ID, pr)
        # Transition queued -> in_progress (sequence=2) -> completed/success (sequence=3)
        p_prog = {"commit_oid": pr["head_oid"], "context": "ci/e2e", "status": "in_progress", "conclusion": None, "attempt": 1, "sequence": 2, "output": "Running"}
        b_prog = json.dumps(p_prog, sort_keys=True, separators=(",", ":")).encode("utf-8")
        st1, r1 = webhooks.post_ci_callback(hk["id"], "cb-ev-1", webhooks.signature_header(secret, b_prog), p_prog)
        self.assertEqual((st1, r1["check_run"]["status"]), (200, "in_progress"))

        p_done = {"commit_oid": pr["head_oid"], "context": "ci/e2e", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 3, "output": "Passed"}
        b_done = json.dumps(p_done, sort_keys=True, separators=(",", ":")).encode("utf-8")
        st2, r2 = webhooks.post_ci_callback(hk["id"], "cb-ev-2", webhooks.signature_header(secret, b_done), p_done)
        self.assertEqual((st2, r2["check_run"]["status"], r2["check_run"]["conclusion"]), (200, "completed", "success"))

    def test_t1_f23_04_ci_callback_event_id_idempotent_replay_returns_cached_result(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "replay-callback-secret"
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9103/ci", secret, ci_contexts=["ci/unit"])
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Replay CB", "refs/heads/feature", "refs/heads/main")
        payload = {"commit_oid": pr["head_oid"], "context": "ci/unit", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2, "output": "OK"}
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        sig = webhooks.signature_header(secret, raw)
        s1, res1 = webhooks.post_ci_callback(hk["id"], "cb-idem-1", sig, payload)
        s2, res2 = webhooks.post_ci_callback(hk["id"], "cb-idem-1", sig, payload)
        self.assertEqual((s1, s2), (200, 200))
        self.assertFalse(res1["replayed"])
        self.assertTrue(res2["replayed"])
        self.assertEqual(res1["check_run"], res2["check_run"])

    def test_t1_f23_05_completed_ci_callbacks_unlock_branch_protected_pr_merge(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "unlock-merge-secret-01"
        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/gate"])
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9104/ci", secret)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Gated PR", "refs/heads/feature", "refs/heads/main")
        webhooks.on_pull_synchronized(ALICE, DEFAULT_REPO_ID, pr)
        pulls.create_review(ALICE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])
        # Merge blocked while ci/gate is still queued
        self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 409)
        # Complete ci/gate via signed webhook callback
        cb_payload = {"commit_oid": pr["head_oid"], "context": "ci/gate", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2, "output": "Green"}
        cb_bytes = json.dumps(cb_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        webhooks.post_ci_callback(hk["id"], "cb-gate-ok", webhooks.signature_header(secret, cb_bytes), cb_payload)
        st_m, merged = pulls.merge_pull(ALICE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])
        self.assertEqual((st_m, merged["state"]), (200, "merged"))

