    def test_t1_f24_04_role_gated_endpoint_matrix_across_browse_lfs_pulls_webhooks_and_admin(self) -> None:
        git_fx, _, rbac = self.make_rbac_rig(with_webhooks=True, with_browse_lfs=True)
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "bob", "read")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "charlie", "triage")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "dave", "write")
        # Read user (bob) can browse refs and download LFS, but cannot create PR or upload LFS
        self.assertEqual(rbac.browse_refs(BOB, DEFAULT_REPO_ID)[0], 200)
        self.assertEqual(rbac.create_pull(BOB, DEFAULT_REPO_ID, "Bob PR", "refs/heads/feature", "refs/heads/main")[0], 403)
        self.assertEqual(rbac.lfs_batch(BOB, DEFAULT_REPO_ID, "upload", [{"oid": "a" * 64, "size": 10}])[0], 403)
        # Write user (dave) can create PR, upload LFS, and run ref-transactions, but cannot manage branch rules or webhooks
        st_pr, pr = rbac.create_pull(DAVE, DEFAULT_REPO_ID, "Dave PR", "refs/heads/feature", "refs/heads/main")
        self.assertEqual((st_pr, pr["author_id"], pr["tenant_id"]), (201, DAVE_ID, ALICE_ID))
        self.assertEqual(rbac.lfs_batch(DAVE, DEFAULT_REPO_ID, "upload", [{"oid": "a" * 64, "size": 10}])[0], 200)
        self.assertEqual(rbac.upsert_branch_rule(DAVE, DEFAULT_REPO_ID, "main", required_approvals=1)[0], 403)
        # Triage user (charlie) can submit commented review, but not approved review
        self.assertEqual(rbac.create_review(CHARLIE, DEFAULT_REPO_ID, pr["number"], "commented", pr["head_oid"], body="Triaged")[0], 201)
        self.assertEqual(rbac.create_review(CHARLIE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])[0], 403)
        # Non-member (eve) gets 404 (no existence leak)
        self.assertEqual(rbac.browse_refs(EVE, DEFAULT_REPO_ID)[0], 404)
        self.assertEqual(rbac.post_ref_transaction(DAVE, DEFAULT_REPO_ID, 1, [{"ref_name": "refs/tags/v-dave", "old_oid": ZERO_OID, "new_oid": git_fx.commits["c2"]}])[0], 200)

