    def test_t1_f25_01_multi_reviewer_distinct_write_plus_approvals_unlock_protected_merge(self) -> None:
        _, _, rbac = self.make_rbac_rig()
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "bob", "write")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "charlie", "maintain")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "dave", "write")
        rbac.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_approvals=2, prevent_self_approval=True)
        _, pr = rbac.create_pull(BOB, DEFAULT_REPO_ID, "Team PR", "refs/heads/feature", "refs/heads/main")
        # 1st approval by charlie -> still 1 short of 2 required approvals
        rbac.create_review(CHARLIE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])
        self.assertEqual(rbac.merge_pull(CHARLIE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 409)
        # Duplicate approval by charlie does not count as 2nd distinct reviewer
        rbac.create_review(CHARLIE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])
        self.assertEqual(rbac.merge_pull(CHARLIE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 409)
        # 2nd distinct approval by dave unlocks merge
        rbac.create_review(DAVE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])
        st_m, merged = rbac.merge_pull(CHARLIE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])
        self.assertEqual((st_m, merged["state"]), (200, "merged"))

