    def test_t1_f25_05_audit_log_cursor_pagination_and_actor_action_timestamp_filtering(self) -> None:
        _, _, rbac = self.make_rbac_rig()
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "bob", "maintain", now_unix=100)
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "charlie", "write", now_unix=200)
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "dave", "read", now_unix=300)
        rbac.upsert_branch_rule(BOB, DEFAULT_REPO_ID, "main", required_approvals=1, now_unix=400)

        _, p1 = rbac.list_audit_log(ALICE, DEFAULT_REPO_ID, after=0, limit=2)
        _, p2 = rbac.list_audit_log(ALICE, DEFAULT_REPO_ID, after=p1["next_after"], limit=2)
        self.assertEqual(len(p1["items"]), 2)
        self.assertEqual(len(p2["items"]), 2)
        self.assertIsNone(p2["next_after"])

        _, bob_only = rbac.list_audit_log(ALICE, DEFAULT_REPO_ID, filter_actor="bob")
        self.assertEqual(len(bob_only["items"]), 1)
        self.assertEqual(bob_only["items"][0]["action"], "branch_rule.updated")

        _, window = rbac.list_audit_log(ALICE, DEFAULT_REPO_ID, since=150, until=350)
        self.assertEqual([e["target_name"] for e in window["items"]], ["charlie", "dave"])

    # =========================================================================
    # Feature F26: Track C — Pando Online Repository Migration State Machine (5 Tests)
    # =========================================================================
    def test_t1_f26_01_step_by_step_online_migration_copy_verify_drain_fence_switchover(self) -> None:
        git_fx = self.clone_git_fixture("f26_step.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f26_store")
        r1 = pando.migrate_step(git_fx.bare_dir, "copy")
        self.assertEqual((r1["state"], pando.migration_state, pando.storage_backend), ("COPYING", "copying", "gitfs"))
        r2 = pando.migrate_step(git_fx.bare_dir, "verify")
        self.assertEqual((r2["state"], r2["diff_report"]["parity"]), ("VERIFIED", True))
        r3 = pando.migrate_step(git_fx.bare_dir, "drain")
        self.assertEqual((r3["state"], pando.write_paused), ("DRAINED", True))
        r4 = pando.migrate_step(git_fx.bare_dir, "fence")
        self.assertEqual((r4["state"], r4["old_storage_generation"], r4["new_storage_generation"]), ("FENCED", 1, 2))
        r5 = pando.migrate_step(git_fx.bare_dir, "switchover")
        self.assertEqual((r5["state"], pando.storage_backend, pando.write_paused, pando.storage_generation), ("SWITCHED_OVER", "pando", False, 2))

