        self.assertTrue(res["diff_report"]["parity"])
        st_refs, refs_body = pando.http_get_refs(DEFAULT_REPO_ID, "alice")
        self.assertEqual(st_refs, 200)
        self.assertEqual(refs_body["storage_generation"], 2)
        self.assertEqual(refs_body["refs"]["refs/heads/main"], git_fx.commits["c2"])
