    def test_t1_f27_02_rollback_preserves_post_switchover_pando_commits_and_new_branches_in_gitfs(self) -> None:
        git_fx = self.clone_git_fixture("f27_rb2.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f27_rb2_store")
        pando.migrate_full(git_fx.bare_dir)
        # Create a brand-new commit in a temporary staging bare repo, pack it, and push to Pando
        staging_git = self.clone_git_fixture("f27_staging.git")
        t_new = staging_git.write_tree({"pando_only.txt": ("100644", b"committed on pando after switchover\n")})
        c_new = staging_git.commit_tree(t_new, [git_fx.commits["c3"]], "Post-switchover Pando commit")
        inc_pack = staging_git.run_git(
            ["pack-objects", "--stdout", "--revs", "--delta-base-offset"],
            input_bytes=f"{c_new}\n^{git_fx.commits['c3']}\n".encode("ascii"),
        ).stdout
        st_rec, _ = pando.pando_receive_pack(
            "alice",
            [
                ("refs/heads/feature", git_fx.commits["c3"], c_new),
                ("refs/heads/pando-branch", ZERO_OID, c_new),
            ],
            pack_bytes=inc_pack,
            expected_storage_gen=2,
        )
        self.assertEqual(st_rec, 200)
        # Rollback to git_fx.bare_dir (which did NOT have c_new before rollback)
        rb = pando.rollback_to_gitfs(git_fx.bare_dir)
        self.assertEqual(rb["post_switchover_commits"], 1)
        self.assertEqual(git_fx.resolve_ref("refs/heads/feature"), c_new)
        self.assertEqual(git_fx.resolve_ref("refs/heads/pando-branch"), c_new)
        self.assertEqual(git_fx.cat_file_type(c_new), "commit")

