    # Feature F28: Track D — Cross-Node Dirty Workspace Snapshot Transfer (5 Tests)
    # =========================================================================
    def test_t1_f28_01_push_remote_and_pull_remote_restore_dirty_staged_untracked_and_symlinks_on_node_b(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "node_a")
        node_b = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "node_b")
        remote_cas = self.tmp_path / "remote_cas"
        ws_a = node_a.init_workspace(
            "ws_a",
            {"README.md": b"# Node A\n", "src/lib.rs": b"pub fn v1() {}\n", "run.sh": b"#!/bin/sh\necho v1\n", ".rootyardignore": b"*.tmp\n"},
        )
        os.chmod(ws_a / "run.sh", 0o755)
        subprocess.run(["git", "-C", str(ws_a), "add", "-A"], env=GIT_ENV, check=True)
        subprocess.run(["git", "-C", str(ws_a), "commit", "--amend", "-m", "Init with mode"], stdout=subprocess.PIPE, env=GIT_ENV, check=True)
        node_a.workspaces["ws_a"]["base_oid"] = subprocess.run(["git", "-C", str(ws_a), "rev-parse", "HEAD"], stdout=subprocess.PIPE, env=GIT_ENV, check=True).stdout.decode("ascii").strip()

        # Create staged, unstaged modified, untracked, relative symlink, and ignored file on Node A
        (ws_a / "README.md").write_bytes(b"# Node A staged\n")
        subprocess.run(["git", "-C", str(ws_a), "add", "README.md"], env=GIT_ENV, check=True)
        (ws_a / "src/lib.rs").write_bytes(b"pub fn dirty_v2() {}\n")
        (ws_a / "untracked.txt").write_bytes(b"untracked payload\n")
        os.symlink("README.md", ws_a / "readme_link")
        (ws_a / "scratch.tmp").write_bytes(b"ignored")

        push_res = node_a.push_remote("ws_a", remote_cas, quiescent=True)
        self.assertEqual(push_res["durability"], "remote_cas_committed")
        self.assertEqual(push_res["excluded_ignored_entries"], 1)
        self.assertGreaterEqual(push_res["blobs_uploaded"], 4)

        pull_res = node_b.pull_remote(remote_cas, push_res["checkpoint_id"], "ws_b", agent_id="agent-node-b")
        self.assertEqual(pull_res["state"], "restored_from_remote")
        st_a = node_a.workspace_status("ws_a")
        st_b = node_b.workspace_status("ws_b")
        self.assertEqual(st_a["base_oid"], st_b["base_oid"])
        self.assertEqual(st_a["staged"], st_b["staged"])
        self.assertEqual(st_a["modified"], st_b["modified"])
        self.assertEqual(st_a["untracked"], st_b["untracked"])
        self.assertEqual(st_a["managed_entries"], st_b["managed_entries"])
        self.assertFalse((node_b.workspaces["ws_b"]["repo_path"] / "scratch.tmp").exists())

    def test_t1_f28_02_cas_blob_deduplication_across_incremental_checkpoints(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "dedup_a")
