    def test_t1_f28_03_bidirectional_node_a_to_node_b_and_back_with_three_way_changeset_apply(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "bi_a")
        node_b = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "bi_b")
        remote_cas = self.tmp_path / "bi_cas"
        node_a.init_workspace("ws_a", {"mod_a.rs": b"fn a() {}\n", "mod_b.rs": b"fn b() {}\n"})
        ckpt_base = node_a.create_checkpoint("ws_a", "ckpt-base")
        node_a.push_remote(ckpt_base, remote_cas, quiescent=True)
        node_b.pull_remote(remote_cas, ckpt_base, "ws_b")

        # Node B edits mod_b.rs and pushes ckpt-b to remote CAS; Node A edits mod_a.rs locally
        (node_b.workspaces["ws_b"]["repo_path"] / "mod_b.rs").write_bytes(b"fn b_from_node_b() {}\n")
        ckpt_b = node_b.create_checkpoint("ws_b", "ckpt-b")
        node_b.push_remote(ckpt_b, remote_cas, quiescent=True)
        (node_a.workspaces["ws_a"]["repo_path"] / "mod_a.rs").write_bytes(b"fn a_from_node_a() {}\n")

        # Node A pulls ckpt-b into local checkpoint store and applies 3-way changeset (ckpt-base -> ckpt-b)
        node_a.pull_remote(remote_cas, ckpt_b, "ws_b_shadow")
        cs_b = node_a.create_changeset(ckpt_base, ckpt_b, "cs-from-b")
        applied = node_a.apply_changeset("ws_a", cs_b, quiescent=True)
        self.assertEqual(applied["applied_changes"], 1)
        self.assertEqual((node_a.workspaces["ws_a"]["repo_path"] / "mod_a.rs").read_bytes(), b"fn a_from_node_a() {}\n")
        self.assertEqual((node_a.workspaces["ws_a"]["repo_path"] / "mod_b.rs").read_bytes(), b"fn b_from_node_b() {}\n")

