    def test_t1_f28_05_cas_shards_enforce_two_hex_prefix_layout_and_mode_0600(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "layout_a")
        remote_cas = self.tmp_path / "layout_cas"
        node_a.init_workspace("ws_a", {"hello.txt": b"cas shard test\n"})
