    def test_t1_f29_02_mounted_namespace_enforces_readonly_modes_and_source_workspace_isolation(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "ns_2")
        ws_svc = wfx.init_workspace("ws_svc", {"cfg.toml": b"port = 8080\n", "bin.sh": b"#!/bin/sh\n"})
        os.chmod(ws_svc / "bin.sh", 0o755)
        ckpt = wfx.create_checkpoint("ws_svc", "ckpt-svc")
        ns = wfx.namespace_mount("ns-iso", {"services/svc": ckpt})
        tree_p = Path(ns["view_path"])
        cfg_ro = tree_p / "services/svc/cfg.toml"
        bin_ro = tree_p / "services/svc/bin.sh"
        self.assertEqual(stat.S_IMODE(cfg_ro.stat().st_mode), 0o444)
        self.assertEqual(stat.S_IMODE(bin_ro.stat().st_mode), 0o555)
        self.assertNotEqual(cfg_ro.stat().st_ino, (ws_svc / "cfg.toml").stat().st_ino)
        # Mutating source workspace after mount does not alter mounted namespace
        (ws_svc / "cfg.toml").write_bytes(b"port = 9999\n")
        self.assertEqual(cfg_ro.read_bytes(), b"port = 8080\n")
        self.assertTrue(wfx.verify_namespace("ns-iso")["verified"])

