    # Feature F34: Track 1 — Untrusted Markdown XSS Sanitization & UTF-8 Boundary-Safe Large Blob Preview (5 Tests)
    # =========================================================================
    def test_t1_f34_01_markdown_sanitizer_strips_script_svg_iframe_and_event_handler_attributes(self) -> None:
        _, _, _, _, web = self.make_web_ui_rig()
        hostile_md = (
            'Hello <script>alert("xss")</script> '
            '<svg onload="alert(1)"><circle r="10"/></svg> '
            '<img src="x" onerror="fetch(\'http://evil\')"> '
            '<iframe src="https://evil.example"></iframe> world!'
        )
        rendered = web.render_safe_markdown(hostile_md)
        self.assertNotIn("<script", rendered.lower())
        self.assertNotIn("<svg", rendered.lower())
        self.assertNotIn("<iframe", rendered.lower())
        self.assertNotIn("onload=", rendered.lower())
        self.assertNotIn("onerror=", rendered.lower())
        self.assertIn("Hello", rendered)
        self.assertIn("world!", rendered)

    def test_t1_f34_02_markdown_sanitizer_blocks_javascript_data_vbscript_and_entity_obfuscated_uris(self) -> None:
        _, _, _, _, web = self.make_web_ui_rig()
        payload = (
            "[click1](javascript:alert(1)) "
            "[click2](&#106;&#97;&#118;&#97;&#115;&#99;&#114;&#105;&#112;&#116;&#58;alert(2)) "
            "[click3](java&#x09;script:alert(3)) "
            "[click4](data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==) "
            "[safe](https://example.com/docs)"
        )
        rendered = web.render_safe_markdown(payload)
        self.assertNotIn("javascript:", rendered.lower())
        self.assertNotIn("data:text/html", rendered.lower())
        self.assertEqual(rendered.count('data-sanitized-url="blocked"'), 4)
        self.assertIn('href="https://example.com/docs"', rendered)

