    def test_t1_f34_04_utf8_multibyte_codepoints_split_at_max_bytes_boundary_are_trimmed_cleanly_not_marked_binary(self) -> None:
        git_fx, _, _, _, web = self.make_web_ui_rig()
        # Construct UTF-8 text where 4-byte emoji 🚀 (\xf0\x9f\x9a\x80) straddles byte 512
        prefix_ascii = b"A" * 510
        emoji_stream = "🚀🔥漢字" * 40
        raw_utf8 = prefix_ascii + emoji_stream.encode("utf-8")
        proc = subprocess.run(
            ["git", f"--git-dir={git_fx.bare_dir}", "hash-object", "-w", "--stdin"],
            input=raw_utf8,
            stdout=subprocess.PIPE,
            env=GIT_ENV,
            check=True,
        )
        utf8_oid = proc.stdout.decode("ascii").strip()
        # At max_bytes=512, bytes 510..512 are \xf0\x9f (half of 🚀)
        st, prev = web.build_blob_preview(utf8_oid, max_bytes=512)
        self.assertEqual(st, 200)
        self.assertFalse(prev["is_binary"])
        self.assertTrue(prev["truncated"])
        self.assertEqual(prev["preview_bytes"], 510)
        self.assertEqual(prev["content_preview"], "A" * 510)

