    def test_t1_f35_02_object_store_get_hydrates_evicted_local_pack_from_object_store_and_verifies_parse(self) -> None:
        pfx = PandoDeltaGraphExportFixture(self.tmp_path / "pando_f35_2")
        pfx.configure_object_store(tier="s3_compatible", bucket="hydrate-bucket")
        blob_data = b"hydrated from remote object store\n"
        blob_oid = pfx.git_oid("blob", blob_data)
        pack_b = pfx.build_pack_from_entries([(3, blob_data, None, None)])
        pack_fp, idx_fp = pfx.register_manifest_pack("pack-hyd-1", pack_b, b"idx-hyd-1")
        pfx.object_store_put("pack-hyd-1")
        # Evict local pack and idx files from local objects_dir
        pack_fp.unlink()
        idx_fp.unlink()
        self.assertFalse(pack_fp.exists())
        get_res = pfx.object_store_get("pack-hyd-1")
        self.assertTrue(get_res["verified"])
        self.assertTrue(pack_fp.is_file())
        parsed = pfx.parse_and_resolve_pack(pack_fp.read_bytes())
        self.assertIn(blob_oid, parsed["objects"])

