    # =========================================================================
    # Feature F36: Track 2 — Pando Multi-Pack Compaction / Repack & Storage Backend Gateway Routing (5 Tests)
    # =========================================================================
    def test_t1_f36_01_repack_consolidates_multiple_packs_into_single_deterministic_pack_and_prunes_unreachable_objects(self) -> None:
        git_fx = self.clone_git_fixture("repack_src.git")
        pfx = PandoDeltaGraphExportFixture(self.tmp_path / "pando_f36_1")
        pfx.migrate_full(git_fx.bare_dir)
        # Add a second pack with a reachable commit and a third pack with an unreachable orphan blob
        p2_res = pfx.receive_incremental_commit("refs/heads/main", "post_repack.txt", b"reachable after repack\n", message="Reachable commit")
        orphan_pack = pfx.build_pack_from_entries([(3, b"unreachable orphan blob data\n", None, None)])
        pfx.register_manifest_pack("pack-orphan-1", orphan_pack, b"idx-orphan-1")
        self.assertEqual(len(pfx.manifests), 3)

        rep = pfx.repack(prune_superseded=True)
        self.assertEqual(rep["state"], "COMPLETED")
        self.assertEqual(rep["compacted_packs"], 3)
        self.assertGreaterEqual(rep["pruned_unreachable_objects"], 1)
        self.assertEqual(rep["retired_packs"], 3)
        self.assertEqual(len(pfx.manifests), 1)
        # Verify reachable graph and diff_export parity after compaction
        new_pack_path = pfx.objects_dir / f"{rep['new_pack_id']}.pack"
        parsed = pfx.parse_and_resolve_pack(new_pack_path.read_bytes())
        self.assertIn(p2_res["commit_oid"], parsed["objects"])

    def test_t1_f36_02_repack_preserves_explicit_pin_oids_and_active_snapshot_pinned_packs(self) -> None:
        git_fx = self.clone_git_fixture("repack_pin.git")
        pfx = PandoDeltaGraphExportFixture(self.tmp_path / "pando_f36_2")
        pfx.migrate_full(git_fx.bare_dir)
        first_pid = next(iter(pfx.manifests.keys()))
        pinned_blob = b"explicitly pinnedci artifact\n"
        pinned_oid = pfx.git_oid("blob", pinned_blob)
        p_pin = pfx.build_pack_from_entries([(3, pinned_blob, None, None)])
        pfx.register_manifest_pack("pack-pin-1", p_pin, b"idx-pin-1")
        # Register an active unexpired snapshot referencing first_pid
        pfx.snapshots.append({"id": "snap-active", "expires_at": 5000.0, "pinned_pack_id": first_pid, "storage_generation": pfx.storage_generation})

        rep = pfx.repack(prune_superseded=True, pin_oids=[pinned_oid], now_ts=1000.0)
        self.assertEqual(rep["preserved_pinned_objects"], 1)
        self.assertIn(first_pid, rep["protected_packs"])
        # Protected pack remains on disk while unprotected superseded pack is unlinked
        self.assertTrue((pfx.objects_dir / f"{first_pid}.pack").is_file())
        self.assertFalse((pfx.objects_dir / "pack-pin-1.pack").exists())
        # Pinned blob is inside the new compacted pack
        new_parsed = pfx.parse_and_resolve_pack((pfx.objects_dir / f"{rep['new_pack_id']}.pack").read_bytes())
        self.assertIn(pinned_oid, new_parsed["objects"])

    def test_t1_f36_03_single_pack_with_no_unreachable_objects_returns_idempotent_noop_repack(self) -> None:
        git_fx = self.clone_git_fixture("repack_noop.git")
        pfx = PandoDeltaGraphExportFixture(self.tmp_path / "pando_f36_3")
        pfx.migrate_full(git_fx.bare_dir)
