    def test_t1_f37_05_repeated_vfs_hydrate_is_idempotent_and_preserves_dirty_cow_modifications(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_f37_5")
        wfx.init_workspace("ws_idem", {"code.rs": b"fn v1() {}\n"})
        ckpt = wfx.create_checkpoint("ws_idem", "ckpt-idem")
        mnt = wfx.vfs_mount("vfs-idem", ckpt)
        r1 = wfx.vfs_hydrate("vfs-idem", ["code.rs"], cow_write=True)
        self.assertEqual(r1["newly_hydrated"], 1)
        # Mutate hydrated file in place (Copy-on-Write dirty state)
        code_fp = Path(mnt["mount_path"]) / "code.rs"
        code_fp.write_bytes(b"fn v2_dirty() {}\n")
        # Re-hydrating must preserve dirty Copy-on-Write content without overwriting
        r2 = wfx.vfs_hydrate("vfs-idem", ["code.rs"])
        self.assertEqual(r2["preserved_dirty"], 1)
        self.assertEqual(code_fp.read_bytes(), b"fn v2_dirty() {}\n")

