    # Feature F38: Track 3 — Workspace-Lab Copy-on-Write Dirty File Tracking, Ignore-Aware Status & Clean Blob Eviction (5 Tests)
    # =========================================================================
    def test_t1_f38_01_vfs_status_classifies_dehydrated_hydrated_clean_and_hydrated_dirty_states(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_f38_1")
        wfx.init_workspace("ws_st", {"a.txt": b"aaa\n", "b.txt": b"bbb\n", "c.txt": b"ccc\n", "d.sh": b"#!/bin/sh\n"})
        ckpt = wfx.create_checkpoint("ws_st", "ckpt-st")
        mnt = wfx.vfs_mount("vfs-st", ckpt)
        wfx.vfs_hydrate("vfs-st", ["b.txt", "c.txt", "d.sh"], cow_write=True)
        mount_dir = Path(mnt["mount_path"])
        (mount_dir / "c.txt").write_bytes(b"ccc-modified\n")
        os.chmod(mount_dir / "d.sh", 0o755)
        (mount_dir / "new_file.txt").write_bytes(b"added\n")

        st = wfx.vfs_status("vfs-st")
        self.assertEqual(st["dehydrated"], ["a.txt"])
        self.assertEqual(st["hydrated_clean"], ["b.txt"])
        self.assertEqual(st["modified"], ["c.txt"])
        self.assertEqual(st["mode_changed"], ["d.sh"])
        self.assertEqual(st["added"], ["new_file.txt"])

    def test_t1_f38_02_vfs_status_respects_gitignore_and_rootyardignore_with_negation_rules(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_f38_2")
        wfx.init_workspace(
            "ws_ig",
            {
                ".gitignore": b"*.log\n!important.log\n",
                ".rootyardignore": b"cache/\n",
                "main.rs": b"fn main() {}\n",
            },
        )
        ckpt = wfx.create_checkpoint("ws_ig", "ckpt-ig")
        mnt = wfx.vfs_mount("vfs-ig", ckpt)
        mount_dir = Path(mnt["mount_path"])
        (mount_dir / "debug.log").write_bytes(b"ignored log\n")
        (mount_dir / "important.log").write_bytes(b"tracked log!\n")
        (mount_dir / "cache").mkdir(parents=True, exist_ok=True)
        (mount_dir / "cache/tmp.bin").write_bytes(b"ignored cache\n")

        st = wfx.vfs_status("vfs-ig")
        self.assertEqual(st["added"], ["important.log"])
        self.assertIn("debug.log", st["ignored"])
        self.assertIn("cache/tmp.bin", st["ignored"])

    def test_t1_f38_03_vfs_evict_reclaims_hydrated_clean_blobs_and_prunes_empty_directories(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_f38_3")
        wfx.init_workspace("ws_ev", {"deep/nested/dir/blob.bin": b"X" * 4096, "keep.txt": b"keep\n"})
