    def test_t1_f38_04_vfs_evict_with_skip_dirty_evicts_clean_files_while_preserving_dirty_cow_files(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_f38_4")
        wfx.init_workspace("ws_sd", {"clean.txt": b"clean\n", "dirty.txt": b"orig\n"})
        ckpt = wfx.create_checkpoint("ws_sd", "ckpt-sd")
        mnt = wfx.vfs_mount("vfs-sd", ckpt)
        wfx.vfs_hydrate("vfs-sd", ["*"], cow_write=True)
        mount_dir = Path(mnt["mount_path"])
        (mount_dir / "dirty.txt").write_bytes(b"dirty edit\n")

        ev = wfx.vfs_evict("vfs-sd", quiescent=True, skip_dirty=True)
        self.assertEqual(ev["evicted_paths"], ["clean.txt"])
        self.assertEqual(ev["protected_dirty_entries"], 1)
        self.assertFalse((mount_dir / "clean.txt").exists())
        self.assertEqual((mount_dir / "dirty.txt").read_bytes(), b"dirty edit\n")

