    def test_t1_f40_02_automated_node_failover_promotes_replica_fences_old_primary_and_bumps_storage_generation(self) -> None:
        _, pulls, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        st_fo, fo = sharding.execute_failover(ALICE, DEFAULT_REPO_ID, "shard-replica-1", reason="Primary maintenance", now_unix=1000)
        self.assertEqual(st_fo, 200)
        self.assertEqual(fo["state"], "promoted")
        self.assertEqual(fo["transitions"], ["draining", "fenced", "verified", "promoted"])
        self.assertEqual(fo["old_primary_node_id"], "shard-primary-1")
        self.assertEqual(fo["new_primary_node_id"], "shard-replica-1")
        self.assertEqual(fo["new_route_epoch"], 2)
        self.assertEqual(fo["new_storage_generation"], 2)
        self.assertEqual(pulls.storage_generation, 2)
        # Old primary is now fenced
        _, old_node = sharding.get_node(ALICE_RO, "shard-primary-1")
        self.assertEqual((old_node["role"], old_node["status"], old_node["fenced_epoch"]), ("fenced", "fenced", 2))

    def test_t1_f40_03_split_brain_write_from_fenced_old_primary_or_stale_epoch_is_rejected_with_409(self) -> None:
        _, _, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        sharding.execute_failover(ALICE, DEFAULT_REPO_ID, "shard-replica-1", now_unix=1000)
        # Old primary attempting write with stale epoch=1 or node_id="shard-primary-1" is fenced (409)
        err_epoch = sharding.check_before_push(DEFAULT_REPO_ID, caller_route_epoch=1, now_unix=1000)
        self.assertIsNotNone(err_epoch)
        self.assertEqual(err_epoch[0], 409)
        err_node = sharding.check_before_push(DEFAULT_REPO_ID, caller_node_id="shard-primary-1", now_unix=1000)
        self.assertIsNotNone(err_node)
        self.assertEqual(err_node[0], 409)

    def test_t1_f40_04_degradation_drill_pauses_writes_while_serving_reads_from_watermark_qualified_replica(self) -> None:
        git_fx, pulls, browse, _, sharding = self.make_sharding_rig(seed_cluster=True)
        st_deg, deg = sharding.set_degradation_drill(ALICE, DEFAULT_REPO_ID, degraded_readonly=True, now_unix=1000)
        self.assertEqual((st_deg, deg["degraded_readonly"]), (200, True))
        # Writes are blocked with 409 during degradation drill
        st_tx, _ = browse.post_ref_transaction(
            ALICE,
            DEFAULT_REPO_ID,
            storage_generation=pulls.storage_generation,
            updates=[{"ref_name": "refs/heads/blocked-br", "old_oid": ZERO_OID, "new_oid": git_fx.commits["c2"]}],
        )
        self.assertEqual(st_tx, 409)
        # Reads transparently fail over to healthy replica
        st_rd, rd = sharding.resolve_repo_route(ALICE_RO, DEFAULT_REPO_ID, operation="read", now_unix=1000)
        self.assertEqual((st_rd, rd["selected_role"], rd["selected_node_id"]), (200, "replica", "shard-replica-1"))

