        self.assertEqual((st_rec, rec["degraded_readonly"]), (200, False))
        st_tx, _ = browse.post_ref_transaction(
            ALICE,
            DEFAULT_REPO_ID,
            storage_generation=pulls.storage_generation,
            updates=[{"ref_name": "refs/heads/recovered-br", "old_oid": ZERO_OID, "new_oid": git_fx.commits["c2"]}],
        )
