        e1 = vfx.project_history("view-inc", "ns-inc", "rev-1", strategy="deterministic_history", view_epoch=1)
        self.assertEqual((e1["reused_commits"], e1["newly_projected_commits"]), (0, 2))
        vfx.advance_repo("r-inc", {"a.txt": b"3\n"}, message="c3")
