        _, pr_conf = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Conflict PR", "refs/heads/conflict_br", "refs/heads/main")
        self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, pr_conf["number"], 1, pr_conf["head_oid"], pr_conf["base_oid"], strategy="merge_commit")[0], 409)

