    def test_t2_f12_05_corrupted_on_disk_blob_symlink_and_quota_exceeded_fail_closed(self) -> None:
        lfs = self.make_lfs_rig()
        p1 = b"a" * 1500
        o1 = hashlib.sha256(p1).hexdigest()
        lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": o1, "size": 1500}])
        self.assertEqual(lfs.put_object(ALICE, DEFAULT_REPO_ID, o1, 1500, [p1], quota_bytes=2048)[0], 200)
        p2 = b"b" * 1000
        o2 = hashlib.sha256(p2).hexdigest()
        lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": o2, "size": 1000}])
        self.assertEqual(lfs.put_object(ALICE, DEFAULT_REPO_ID, o2, 1000, [p2], quota_bytes=2048)[0], 507)
        # Corrupt 1 byte on disk for o1
        (lfs.repo_dir / o1).write_bytes(b"z" + b"a" * 1499)
        self.assertEqual(lfs.get_object(ALICE_RO, DEFAULT_REPO_ID, o1)[0], 503)
        with self.assertRaises(RuntimeError):
            lfs.verify_paired_backup()

