    # =========================================================================
    # Feature F16: Pando Streaming Delta Resolution & Graph Traversal — Boundary & Corner Cases (5 Tests)
    # =========================================================================
    def test_t2_f16_01_delta_cycle_detection_and_max_chain_depth_guard(self) -> None:
        # Build a deep OFS_DELTA chain exceeding max_depth=4
        base_payload = b"hello world"
        delta_nop = bytes([len(base_payload), len(base_payload), len(base_payload)]) + base_payload
        entries: list[tuple[int, bytes, Optional[int], Optional[bytes]]] = [(3, base_payload, None, None)]
        # Build pack with 6 chained OFS_DELTA entries
        raw_pack = bytearray(b"PACK")
        offsets: list[int] = []
        raw_pack.extend(struct.pack(">II", 2, 7))
        # Entry 0: blob
        offsets.append(len(raw_pack))
        raw_pack.append((3 << 4) | len(base_payload))
        raw_pack.extend(zlib.compress(base_payload))
        for i in range(6):
            cur_off = len(raw_pack)
            neg_off = cur_off - offsets[-1]
            offsets.append(cur_off)
            sz = len(delta_nop)
            b0 = (6 << 4) | (sz & 0x0F)
            sz >>= 4
            if sz > 0:
                b0 |= 0x80
            raw_pack.append(b0)
            while sz > 0:
                b_next = sz & 0x7F
                sz >>= 7
                if sz > 0:
                    b_next |= 0x80
                raw_pack.append(b_next)
            raw_pack.append(neg_off & 0x7F)
            raw_pack.extend(zlib.compress(delta_nop))
        raw_pack.extend(hashlib.sha1(bytes(raw_pack)).digest())
        with self.assertRaisesRegex(ValueError, "delta chain depth exceeded"):
            PandoDeltaGraphExportFixture.parse_and_resolve_pack(bytes(raw_pack), max_depth=4)

    def test_t2_f16_02_delta_inflation_size_limit_and_target_size_mismatch_guard(self) -> None:
        base_data = b"a" * 16
        # Delta claims target_size=8, but inserts 12 bytes
        bad_delta = bytes([16, 8, 12]) + (b"b" * 12)
        with self.assertRaisesRegex(ValueError, "delta target size mismatch"):
            PandoDeltaGraphExportFixture.apply_git_delta(base_data, bad_delta)
        # Delta claims target_size=100 > max_object_size=32
        huge_delta = bytes([16, 100, 1]) + b"x"
        with self.assertRaisesRegex(ValueError, "exceeds max_object_size"):
            PandoDeltaGraphExportFixture.apply_git_delta(base_data, huge_delta, max_object_size=32)

    def test_t2_f16_03_delta_copy_out_of_bounds_from_base_object_rejected(self) -> None:
        base_data = b"a" * 20
        # Copy instruction: 0x80 | 0x01 (offset 1b) | 0x10 (size 1b) -> offset=15, size=10 (> 20)
        oob_delta = bytes([20, 10, 0x91, 15, 10])
        with self.assertRaisesRegex(ValueError, "delta copy out of bounds"):
            PandoDeltaGraphExportFixture.apply_git_delta(base_data, oob_delta)
        zero_op_delta = bytes([20, 1, 0x00])
        with self.assertRaisesRegex(ValueError, "invalid delta opcode 0"):
            PandoDeltaGraphExportFixture.apply_git_delta(base_data, zero_op_delta)

    def test_t2_f16_04_corrupt_pack_header_magic_version_or_trailer_checksum_rejected(self) -> None:
        valid_pack = PandoDeltaGraphExportFixture.build_pack_from_entries([(3, b"test", None, None)])
        bad_magic = b"PACX" + valid_pack[4:]
        bad_ver = b"PACK" + struct.pack(">II", 3, 1) + valid_pack[12:]
        bad_trailer = valid_pack[:-1] + bytes([valid_pack[-1] ^ 0x01])
        for invalid in (bad_magic, bad_ver, bad_trailer):
            with self.assertRaises(ValueError):
                PandoDeltaGraphExportFixture.parse_and_resolve_pack(invalid)

