    def test_t2_f18_03_verify_readonly_view_detects_file_tampering_mode_drift_and_rogue_files(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "ws_t2_03")
        wfx.init_workspace("ws_v")
        ckpt = wfx.create_checkpoint("ws_v", "ckpt_v")
        # 1. File content tamper
        v1 = wfx.project_readonly_view(ckpt, self.tmp_path / "v1")
        os.chmod(v1 / "plain.txt", 0o644)
        (v1 / "plain.txt").write_bytes(b"tampered\n")
        os.chmod(v1 / "plain.txt", 0o444)
        with self.assertRaisesRegex(ValueError, "tamper"):
            wfx.verify_readonly_view(ckpt, v1)
        # 2. Mode drift
        v2 = wfx.project_readonly_view(ckpt, self.tmp_path / "v2")
        os.chmod(v2 / "plain.txt", 0o777)
        with self.assertRaisesRegex(ValueError, "mode drift"):
            wfx.verify_readonly_view(ckpt, v2)
        # 3. Rogue extra file
        v3 = wfx.project_readonly_view(ckpt, self.tmp_path / "v3")
        (v3 / "rogue.txt").write_bytes(b"rogue\n")
        with self.assertRaisesRegex(ValueError, "rogue file"):
            wfx.verify_readonly_view(ckpt, v3)

