        self.assertEqual(webhooks.create_webhook(RUNNER_RYJ, DEFAULT_REPO_ID, "http://127.0.0.1:9000/h", "secret-1234")[0], 401)
        self.assertEqual(webhooks.create_webhook(ALICE_RO, DEFAULT_REPO_ID, "http://127.0.0.1:9000/h", "secret-1234")[0], 403)
        self.assertEqual(webhooks.create_webhook(BOB, DEFAULT_REPO_ID, "http://127.0.0.1:9000/h", "secret-1234")[0], 404)
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9000/h", "secret-1234", idempotency_key="wh-k1")
        # Idempotency conflict with different URL
        self.assertEqual(webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9000/other", "secret-1234", idempotency_key="wh-k1")[0], 409)
