        self.assertEqual(webhooks.patch_webhook(ALICE, DEFAULT_REPO_ID, hk["id"], expected_version=99, active=False)[0], 409)
        self.assertEqual(webhooks.patch_webhook(ALICE, DEFAULT_REPO_ID, hk["id"], expected_version=0, active=False)[0], 400)

