    # =========================================================================
    def test_t2_f23_01_ci_callback_rejects_missing_malformed_or_wrong_hmac_signature_with_401(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9110/ci", "correct-secret-key")
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "PR", "refs/heads/feature", "refs/heads/main")
        payload = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "queued", "conclusion": None, "attempt": 1, "sequence": 1}
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        for bad_sig in ("", "sha256=short", "sha256=" + ("G" * 64), webhooks.signature_header("wrong-secret-key", raw)):
            st, _ = webhooks.post_ci_callback(hk["id"], "ev-bad-sig", bad_sig, payload)
            self.assertEqual(st, 401)

    def test_t2_f23_02_ci_callback_rejects_tampered_body_or_inactive_webhook(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "tamper-test-secret"
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9111/ci", secret)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "PR", "refs/heads/feature", "refs/heads/main")
        payload = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 1}
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        sig = webhooks.signature_header(secret, raw)
        # Tamper 1 byte in raw body
        st_t, _ = webhooks.post_ci_callback(hk["id"], "ev-tamper", sig, payload, raw_body_override=raw + b" ")
        self.assertEqual(st_t, 401)
        # Deactivate webhook -> 409
        webhooks.patch_webhook(ALICE, DEFAULT_REPO_ID, hk["id"], expected_version=1, active=False)
        st_inact, _ = webhooks.post_ci_callback(hk["id"], "ev-inact", sig, payload)
        self.assertEqual(st_inact, 409)

    def test_t2_f23_03_ci_callback_event_id_reuse_with_different_payload_rejected_with_409(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "conflict-cb-secret"
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9112/ci", secret)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "PR", "refs/heads/feature", "refs/heads/main")
        p1 = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "in_progress", "conclusion": None, "attempt": 1, "sequence": 1}
        p2 = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2}
        b1 = json.dumps(p1, sort_keys=True, separators=(",", ":")).encode("utf-8")
        b2 = json.dumps(p2, sort_keys=True, separators=(",", ":")).encode("utf-8")
        self.assertEqual(webhooks.post_ci_callback(hk["id"], "ev-same-id", webhooks.signature_header(secret, b1), p1)[0], 200)
        self.assertEqual(webhooks.post_ci_callback(hk["id"], "ev-same-id", webhooks.signature_header(secret, b2), p2)[0], 409)

    def test_t2_f23_04_ci_callback_enforces_monotonic_attempt_sequence_and_status_conclusion_pairing(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "monotonic-cb-secret"
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9113/ci", secret)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "PR", "refs/heads/feature", "refs/heads/main")
        # Completed without conclusion -> 400
        bad_p = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "completed", "conclusion": None, "attempt": 1, "sequence": 1}
        bad_b = json.dumps(bad_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
        self.assertEqual(webhooks.post_ci_callback(hk["id"], "ev-bad-1", webhooks.signature_header(secret, bad_b), bad_p)[0], 400)
        # Advance to attempt=2, sequence=2, then reject stale attempt=1, sequence=9
        ok_p = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "completed", "conclusion": "success", "attempt": 2, "sequence": 2}
        ok_b = json.dumps(ok_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
        self.assertEqual(webhooks.post_ci_callback(hk["id"], "ev-ok-2", webhooks.signature_header(secret, ok_b), ok_p)[0], 200)
        stale_p = {"commit_oid": pr["head_oid"], "context": "ci/test", "status": "completed", "conclusion": "failure", "attempt": 1, "sequence": 9}
        stale_b = json.dumps(stale_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
        self.assertEqual(webhooks.post_ci_callback(hk["id"], "ev-stale-1", webhooks.signature_header(secret, stale_b), stale_p)[0], 409)

    def test_t2_f23_05_pr_synchronize_preserves_already_reported_check_runs_on_same_commit(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
