        pulls.report_check(ALICE, DEFAULT_REPO_ID, pr["head_oid"], "ci/fast", "completed", conclusion="success", attempt=1, sequence=5)
        orch = webhooks.on_pull_synchronized(ALICE, DEFAULT_REPO_ID, pr)
        self.assertEqual(orch["seeded_checks"], [])
        _, chks = pulls.list_checks_for_pull(ALICE_RO, DEFAULT_REPO_ID, pr["number"])
        self.assertEqual(chks["items"][0]["conclusion"], "success")

