    # Feature F26: Track C — Pando Online Repository Migration State Machine — Boundary & Corner Cases (5 Tests)
    # =========================================================================
    def test_t2_f26_01_reject_out_of_order_migration_step_transitions(self) -> None:
        git_fx = self.clone_git_fixture("f26_err1.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f26_err1_store")
        for premature_step in ("verify", "drain", "fence", "switchover"):
            with self.assertRaises(ValueError):
                pando.migrate_step(git_fx.bare_dir, premature_step)
        pando.migrate_step(git_fx.bare_dir, "copy")
        for skipped_step in ("drain", "fence", "switchover"):
            with self.assertRaises(ValueError):
                pando.migrate_step(git_fx.bare_dir, skipped_step)

    def test_t2_f26_02_reject_copy_on_missing_non_bare_or_ref_locked_gitfs_repository(self) -> None:
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f26_err2_store")
        with self.assertRaisesRegex(ValueError, "does not exist"):
            pando.migrate_step(self.tmp_path / "nonexistent.git", "copy")
        non_bare = self.tmp_path / "non_bare"
        non_bare.mkdir()
        subprocess.run(["git", "init", str(non_bare)], stdout=subprocess.PIPE, env=GIT_ENV, check=True)
        with self.assertRaisesRegex(ValueError, "not a valid bare"):
            pando.migrate_step(non_bare, "copy")
        git_fx = self.clone_git_fixture("f26_locked.git")
        lock_file = git_fx.bare_dir / "refs/heads/main.lock"
        lock_file.write_bytes(b"locked")
        with self.assertRaisesRegex(ValueError, "lock"):
            pando.migrate_step(git_fx.bare_dir, "copy")

    def test_t2_f26_03_tampered_pack_between_copy_and_verify_transitions_migration_to_failed(self) -> None:
        git_fx = self.clone_git_fixture("f26_err3.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f26_err3_store")
        pando.migrate_step(git_fx.bare_dir, "copy")
        pack_file = next(pando.objects_dir.glob("*.pack"))
        raw = pack_file.read_bytes()
        pack_file.write_bytes(raw[:-1] + bytes([raw[-1] ^ 0xFF]))
        with self.assertRaisesRegex(ValueError, "verify failed"):
            pando.migrate_step(git_fx.bare_dir, "verify")
        self.assertEqual(pando.migration_state, "failed")
        self.assertEqual(pando.storage_backend, "gitfs")

    def test_t2_f26_04_writes_rejected_while_draining_or_fenced_and_stale_storage_generation_rejected(self) -> None:
        git_fx = self.clone_git_fixture("f26_err4.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f26_err4_store")
        pando.migrate_step(git_fx.bare_dir, "copy")
        pando.migrate_step(git_fx.bare_dir, "verify")
        pando.migrate_step(git_fx.bare_dir, "drain")
        # Both GitFS and Pando reject writes during drain
        self.assertEqual(pando.gitfs_push_commit(git_fx.bare_dir, "refs/heads/main", git_fx.commits["c2"], git_fx.commits["c3"])[0], 409)
        self.assertEqual(pando.pando_receive_pack("alice", [("refs/heads/main", git_fx.commits["c2"], git_fx.commits["c3"])])[0], 409)
        pando.migrate_step(git_fx.bare_dir, "fence")
        pando.migrate_step(git_fx.bare_dir, "switchover")
        # Stale expected_storage_gen=1 rejected on Pando after switchover to gen=2
        self.assertEqual(pando.pando_receive_pack("alice", [("refs/heads/main", git_fx.commits["c2"], git_fx.commits["c3"])], expected_storage_gen=1)[0], 409)

