    # Feature F27: Track C — Pando Post-Switchover Rollback to GitFS — Boundary & Corner Cases (5 Tests)
    # =========================================================================
    def test_t2_f27_01_reject_rollback_when_not_switched_over_or_already_rolled_back(self) -> None:
        git_fx = self.clone_git_fixture("f27_err1.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f27_err1_store")
        with self.assertRaisesRegex(ValueError, "switched_over"):
            pando.rollback_to_gitfs(git_fx.bare_dir)
        pando.migrate_full(git_fx.bare_dir)
        pando.rollback_to_gitfs(git_fx.bare_dir)
        with self.assertRaisesRegex(ValueError, "switched_over"):
            pando.rollback_to_gitfs(git_fx.bare_dir)

    def test_t2_f27_02_corrupt_pando_pack_aborts_rollback_before_mutating_gitfs_refs(self) -> None:
        git_fx = self.clone_git_fixture("f27_err2.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f27_err2_store")
        pando.migrate_full(git_fx.bare_dir)
        pando.pando_receive_pack("alice", [("refs/heads/main", git_fx.commits["c2"], git_fx.commits["c3"])])
        # Corrupt pack on disk before rollback
        pack_file = next(pando.objects_dir.glob("*.pack"))
        raw = pack_file.read_bytes()
        pack_file.write_bytes(raw[:-1] + bytes([raw[-1] ^ 0xFF]))
        with self.assertRaisesRegex(ValueError, "rollback failed"):
            pando.rollback_to_gitfs(git_fx.bare_dir)
        self.assertEqual(pando.migration_state, "failed")
        # GitFS refs were NOT mutated to c3
        self.assertEqual(git_fx.resolve_ref("refs/heads/main"), git_fx.commits["c2"])

    def test_t2_f27_03_rollback_aborts_in_flight_pando_operations_and_purges_snapshots(self) -> None:
        git_fx = self.clone_git_fixture("f27_err3.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f27_err3_store")
        pando.migrate_full(git_fx.bare_dir)
        pando.operations["op-live"] = {"id": "op-live", "repository_id": DEFAULT_REPO_ID, "state": "PREPARED"}
        pando.snapshots = [{"id": "snap-g2", "storage_generation": 2, "expires_at": 9999.0}]
        rb = pando.rollback_to_gitfs(git_fx.bare_dir)
        self.assertEqual(rb["aborted_operations"], 1)
        self.assertEqual(pando.operations["op-live"]["state"], "ABORTED")
        self.assertEqual(pando.snapshots, [])

    def test_t2_f27_04_http_get_migration_enforces_principal_auth_and_acl(self) -> None:
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f27_err4_store")
        self.assertEqual(pando.http_get_migration(DEFAULT_REPO_ID, None)[0], 401)
        self.assertEqual(pando.http_get_migration(DEFAULT_REPO_ID, "eve")[0], 403)
        self.assertEqual(pando.http_get_migration("unknown-repo", "alice")[0], 404)

    def test_t2_f27_05_rollback_fails_closed_if_gitfs_target_is_corrupted(self) -> None:
        git_fx = self.clone_git_fixture("f27_err5.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "f27_err5_store")
        pando.migrate_full(git_fx.bare_dir)
        # Corrupt HEAD in gitfs_dir so git fsck fails
        (git_fx.bare_dir / "HEAD").write_text("ref: refs/heads/../../invalid\n", encoding="utf-8")
        with self.assertRaisesRegex(ValueError, "rollback failed"):
            pando.rollback_to_gitfs(git_fx.bare_dir)
        self.assertEqual(pando.migration_state, "failed")

