    # Feature F28: Track D — Cross-Node Dirty Workspace Snapshot Transfer — Boundary & Corner Cases (5 Tests)
    # =========================================================================
    def test_t2_f28_01_push_remote_rejects_missing_quiescent_flag_or_overlapping_cas_path(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err1")
        node_a.init_workspace("ws_a")
        with self.assertRaisesRegex(ValueError, "--quiescent"):
            node_a.push_remote("ws_a", self.tmp_path / "cas1", quiescent=False)
        with self.assertRaisesRegex(ValueError, "must not overlap"):
            node_a.push_remote("ws_a", node_a.store_root / "nested_cas", quiescent=True)

    def test_t2_f28_02_pull_remote_rejects_corrupted_missing_or_size_mismatched_cas_blob_atomically(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err2_a")
        node_b = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err2_b")
        remote_cas = self.tmp_path / "f28_err2_cas"
        node_a.init_workspace("ws_a", {"file1.txt": b"original content\n"})
        pushed = node_a.push_remote("ws_a", remote_cas, quiescent=True)
        sha = hashlib.sha256(b"original content\n").hexdigest()
        shard = remote_cas / "blobs" / sha[:2] / sha
        os.chmod(shard, 0o600)
        shard.write_bytes(b"corrupted content\n")
        with self.assertRaisesRegex(ValueError, "CAS blob"):
            node_b.pull_remote(remote_cas, pushed["checkpoint_id"], "ws_b")
        self.assertFalse((node_b.workspaces_dir / "ws_b").exists())
        shard.unlink()
        with self.assertRaisesRegex(ValueError, "missing CAS blob"):
            node_b.pull_remote(remote_cas, pushed["checkpoint_id"], "ws_b")

    def test_t2_f28_03_pull_remote_rejects_tampered_remote_manifest_or_uncommitted_state(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err3_a")
        node_b = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err3_b")
        remote_cas = self.tmp_path / "f28_err3_cas"
        node_a.init_workspace("ws_a", {"a.txt": b"ok\n"})
        pushed = node_a.push_remote("ws_a", remote_cas, quiescent=True)
        cid = pushed["checkpoint_id"]
        m_path = remote_cas / "checkpoints" / cid / "manifest.json"
        s_path = remote_cas / "checkpoints" / cid / "manifest.sha256"
        orig_bytes = m_path.read_bytes()
        m_path.write_bytes(orig_bytes + b"\n")
        with self.assertRaisesRegex(ValueError, "manifest.sha256 mismatch"):
            node_b.pull_remote(remote_cas, cid, "ws_b")
        # Valid sha256 but state="STAGING" -> rejected
        doc = json.loads(orig_bytes.decode("utf-8"))
        doc["state"] = "STAGING"
        staging_b = json.dumps(doc, sort_keys=True).encode("utf-8")
        m_path.write_bytes(staging_b)
        s_path.write_text(hashlib.sha256(staging_b).hexdigest(), encoding="utf-8")
        with self.assertRaisesRegex(ValueError, "not in COMMITTED state"):
            node_b.pull_remote(remote_cas, cid, "ws_b")

    def test_t2_f28_04_cas_rejects_symlink_or_hardlink_planted_in_blob_shard(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err4_a")
        node_b = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err4_b")
        remote_cas = self.tmp_path / "f28_err4_cas"
        node_a.init_workspace("ws_a", {"sec.txt": b"secret-blob\n"})
        pushed = node_a.push_remote("ws_a", remote_cas, quiescent=True)
        sha = hashlib.sha256(b"secret-blob\n").hexdigest()
        shard = remote_cas / "blobs" / sha[:2] / sha
        # Replace shard with symlink
        outside = self.tmp_path / "outside.txt"
        outside.write_bytes(b"secret-blob\n")
        shard.unlink()
        os.symlink(outside, shard)
        with self.assertRaisesRegex(ValueError, "symlink forbidden in CAS shard"):
            node_b.pull_remote(remote_cas, pushed["checkpoint_id"], "ws_b")
        # Replace shard with hardlink (st_nlink == 2)
        shard.unlink()
        os.link(outside, shard)
        with self.assertRaisesRegex(ValueError, "hardlink forbidden in CAS shard"):
            node_b.pull_remote(remote_cas, pushed["checkpoint_id"], "ws_b")

    def test_t2_f28_05_fault_injection_during_push_remote_cleans_tmp_and_leaves_no_manifest(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f28_err5_a")
        remote_cas = self.tmp_path / "f28_err5_cas"
        node_a.init_workspace("ws_a", {"f.txt": b"fault-test\n"})
        with self.assertRaisesRegex(RuntimeError, "injected fault"):
            node_a.push_remote("ws_a", remote_cas, quiescent=True, inject_fault_after_tmp=True)
        self.assertEqual(list(remote_cas.rglob(".tmp-*")), [])
        self.assertFalse((remote_cas / "checkpoints").exists())

