    def test_t2_f29_03_namespace_mount_rejects_cross_mount_symlink_escape(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f29_err3")
        wfx.init_workspace("ws_1", {"a.txt": b"1\n"})
        c1 = wfx.create_checkpoint("ws_1", "c1")
        # Tamper checkpoint c1 to include a symlink escaping its mount into sibling mount ../b/a.txt
        ckpt_dir = wfx.checkpoints_dir / c1
        os.symlink("../b/a.txt", ckpt_dir / "files/cross_link")
        m_doc = json.loads((ckpt_dir / "manifest.json").read_text(encoding="utf-8"))
        m_doc["entries"]["cross_link"] = {
            "kind": "symlink",
            "mode": 0o120000,
            "target": "../b/a.txt",
            "sha256": hashlib.sha256(b"symlink:../b/a.txt").hexdigest(),
        }
        mb = json.dumps(m_doc, sort_keys=True, indent=2).encode("utf-8")
        (ckpt_dir / "manifest.json").write_bytes(mb)
        (ckpt_dir / "manifest.sha256").write_text(hashlib.sha256(mb).hexdigest(), encoding="utf-8")
        with self.assertRaisesRegex(ValueError, "escapes workspace root"):
            wfx.namespace_mount("ns-cross", {"a": c1, "b": c1})

    def test_t2_f29_04_verify_namespace_detects_rogue_files_mode_drift_content_tamper_and_upper_dot_git(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f29_err4")
        wfx.init_workspace("ws_1", {"f.txt": b"clean\n"})
        c1 = wfx.create_checkpoint("ws_1", "c1")
        ns = wfx.namespace_mount("ns-tamper", {"pkg/a": c1})
        tree_p = Path(ns["view_path"])
        # 1. Upper .git directory planted
        (tree_p / ".git").mkdir()
        with self.assertRaisesRegex(ValueError, "upper .git"):
            wfx.verify_namespace("ns-tamper")
        (tree_p / ".git").rmdir()
        # 2. Rogue file planted
        (tree_p / "pkg/a/rogue.txt").write_bytes(b"rogue")
        with self.assertRaisesRegex(ValueError, "rogue file"):
            wfx.verify_namespace("ns-tamper")
        (tree_p / "pkg/a/rogue.txt").unlink()
        # 3. Writable mode drift
        os.chmod(tree_p / "pkg/a/f.txt", 0o644)
        with self.assertRaisesRegex(ValueError, "writable mode drift"):
            wfx.verify_namespace("ns-tamper")
        # 4. Content tamper
        (tree_p / "pkg/a/f.txt").write_bytes(b"dirty\n")
        os.chmod(tree_p / "pkg/a/f.txt", 0o444)
        with self.assertRaisesRegex(ValueError, "content tamper"):
            wfx.verify_namespace("ns-tamper")

    def test_t2_f29_05_namespace_git_view_fails_closed_if_underlying_namespace_is_tampered(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "f29_err5")
