    def test_t2_f33_02_reject_insufficient_role_on_web_issue_create_pr_merge_and_audit_views(self) -> None:
        _, _, _, rbac, web = self.make_web_ui_rig()
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, BOB, "read")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, CHARLIE, "triage")
        # Read role cannot create issue (requires triage+)
        self.assertEqual(web.create_issue_web(BOB, DEFAULT_REPO_ID, "Denied issue")[0], 403)
        # Triage role cannot create PR or merge PR (requires write+)
        self.assertEqual(web.create_pull_web(CHARLIE, DEFAULT_REPO_ID, "Denied PR", "refs/heads/feature", "refs/heads/main")[0], 403)
        # Triage role cannot view audit log (requires maintain+)
        self.assertEqual(web.get_audit_view(CHARLIE, DEFAULT_REPO_ID)[0], 403)

