    def test_t2_f35_02_reject_corrupted_multipart_chunk_or_size_mismatch_and_clean_up_staging_parts(self) -> None:
        pfx = PandoDeltaGraphExportFixture(self.tmp_path / "pando_t2_f35_2")
        incomp = b"".join(hashlib.sha256(f"ch-{i}".encode("ascii")).digest() for i in range(100))
        pack_b = pfx.build_pack_from_entries([(3, incomp, None, None)])
        pfx.register_manifest_pack("pack-corrupt-ch", pack_b, b"idx-ch")
        with self.assertRaisesRegex(ValueError, "sha256 mismatch"):
            pfx.object_store_put("pack-corrupt-ch", chunk_size=512, corrupt_chunk_index=1)
        with self.assertRaisesRegex(ValueError, "assembled size"):
            pfx.object_store_put("pack-corrupt-ch", chunk_size=512, corrupt_final_size=len(pack_b) + 99)
        parts_root = pfx.bucket_root / ".parts"
        if parts_root.exists():
            self.assertEqual(list(parts_root.iterdir()), [])

