    def test_t2_f35_04_reject_tampered_remote_cas_blob_during_object_store_get_and_verify(self) -> None:
        pfx = PandoDeltaGraphExportFixture(self.tmp_path / "pando_t2_f35_4")
        pack_b = pfx.build_pack_from_entries([(3, b"untampered remote pack\n", None, None)])
        pack_fp, idx_fp = pfx.register_manifest_pack("pack-tamper-rem", pack_b, b"idx-rem")
        put_res = pfx.object_store_put("pack-tamper-rem")
        pack_fp.unlink()
        idx_fp.unlink()
        # Tamper with remote CAS pack blob in bucket
        cas_p = pfx._bucket_cas_path(put_res["pack_sha256"], ".pack")
        cas_p.write_bytes(pack_b[:-1] + bytes([pack_b[-1] ^ 0xFF]))
        with self.assertRaisesRegex(ValueError, "sha256 mismatch"):
            pfx.object_store_get("pack-tamper-rem")
        self.assertFalse(pack_fp.exists())
        with self.assertRaisesRegex(ValueError, "sha256 mismatch"):
            pfx.object_store_verify()

