    def test_t2_f38_02_reject_vfs_evict_of_dirty_cow_modified_or_mode_changed_file_without_skip_dirty(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_t2_f38_2")
        wfx.init_workspace("ws_dirty_ev", {"mod.txt": b"v1\n", "exec.sh": b"#!/bin/sh\n"})
        ckpt = wfx.create_checkpoint("ws_dirty_ev", "ckpt-de")
        mnt = wfx.vfs_mount("vfs-de", ckpt, inline_threshold=128)
        mount_dir = Path(mnt["mount_path"])
        (mount_dir / "mod.txt").write_bytes(b"v2-dirty\n")
        with self.assertRaisesRegex(ValueError, "cannot evict dirty Copy-on-Write"):
            wfx.vfs_evict("vfs-de", paths_or_globs=["mod.txt"], quiescent=True, skip_dirty=False)
        # Restore content but flip executable mode bit -> still dirty
        (mount_dir / "mod.txt").write_bytes(b"v1\n")
        os.chmod(mount_dir / "exec.sh", 0o755)
        with self.assertRaisesRegex(ValueError, "cannot evict dirty Copy-on-Write"):
            wfx.vfs_evict("vfs-de", paths_or_globs=["exec.sh"], quiescent=True, skip_dirty=False)

    def test_t2_f38_03_vfs_status_detects_hydrated_file_deletion_and_file_to_symlink_type_change_as_dirty(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "vfs_t2_f38_3")
        wfx.init_workspace("ws_del", {"del.txt": b"delete me\n", "type.txt": b"regular\n", "keep.txt": b"keep\n"})
        ckpt = wfx.create_checkpoint("ws_del", "ckpt-del")
        mnt = wfx.vfs_mount("vfs-del", ckpt, inline_threshold=128)
        mount_dir = Path(mnt["mount_path"])
        (mount_dir / "del.txt").unlink()
        (mount_dir / "type.txt").unlink()
        os.symlink("keep.txt", mount_dir / "type.txt")

        st = wfx.vfs_status("vfs-del")
        self.assertEqual(st["deleted"], ["del.txt"])
        self.assertEqual(st["type_changed"], ["type.txt"])
        self.assertIn("del.txt", st["hydrated_dirty"])
        self.assertIn("type.txt", st["hydrated_dirty"])

