    def test_t2_f39_03_reject_route_epoch_or_lease_epoch_regression_and_version_cas_conflicts(self) -> None:
        _, _, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        sharding.renew_node_lease(ALICE, "shard-primary-1", lease_epoch=5, now_unix=1000)
        # Lease epoch regression 4 < 5 rejected with 409
        self.assertEqual(sharding.renew_node_lease(ALICE, "shard-primary-1", lease_epoch=4, now_unix=1000)[0], 409)
        # Stale expected_version on node patch
        self.assertEqual(sharding.patch_node(ALICE, "shard-primary-1", expected_version=99, used_bytes=100)[0], 409)
        # Route epoch regression on repo route
        sharding.configure_repo_route(ALICE, DEFAULT_REPO_ID, primary_node_id="shard-primary-1", route_epoch=3)
        self.assertEqual(sharding.configure_repo_route(ALICE, DEFAULT_REPO_ID, primary_node_id="shard-primary-1", route_epoch=2)[0], 409)

    def test_t2_f39_04_reject_non_admin_node_mutation_and_non_maintain_route_mutation(self) -> None:
        _, _, _, rbac, sharding = self.make_sharding_rig(seed_cluster=True)
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, BOB, "write")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, CHARLIE, "maintain")
        # Maintain role cannot register shard nodes (requires admin)
        self.assertEqual(sharding.upsert_node(CHARLIE, "node-x", "http://127.0.0.1:19999")[0], 403)
        # Write role cannot configure repo shard route (requires maintain+)
        self.assertEqual(sharding.configure_repo_route(BOB, DEFAULT_REPO_ID, primary_node_id="shard-primary-1")[0], 403)

    def test_t2_f39_05_return_503_when_primary_unhealthy_and_all_replicas_lag_required_storage_generation(self) -> None:
        _, pulls, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        pulls.storage_generation = 5
        # Mark primary offline while replicas only have watermark=1 (< 5)
        sharding.patch_node(ALICE, "shard-primary-1", expected_version=1, status="offline")
        st_r, err_r = sharding.resolve_repo_route(ALICE_RO, DEFAULT_REPO_ID, operation="read", min_storage_generation=5, now_unix=1000)
        self.assertEqual(st_r, 503)
        self.assertIn("watermark-qualified", err_r["error"])

    # =========================================================================
    # Feature F40: Track 4 — Epoch Write Fencing & Failover — Boundary & Corner Cases (5 Tests)
    # =========================================================================
    def test_t2_f40_01_reject_write_when_on_disk_fence_marker_missing_corrupted_symlink_or_wrong_mode(self) -> None:
        git_fx, _, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        marker_fp = git_fx.bare_dir / "rootyard-shard-fence.json"
        orig_bytes = marker_fp.read_bytes()

        # 1. Wrong permissions (0644 instead of 0600)
        os.chmod(marker_fp, 0o644)
        self.assertEqual(sharding.check_before_push(DEFAULT_REPO_ID)[0], 409)

        # 2. Corrupted JSON content
        os.chmod(marker_fp, 0o600)
        marker_fp.write_bytes(b"{corrupt json")
        self.assertEqual(sharding.check_before_push(DEFAULT_REPO_ID)[0], 409)

        # 3. Missing marker file
        marker_fp.unlink()
        self.assertEqual(sharding.check_before_push(DEFAULT_REPO_ID)[0], 409)

        # 4. Symlink marker file
        outside_fp = self.tmp_path / "fake_fence.json"
        outside_fp.write_bytes(orig_bytes)
        os.symlink(outside_fp, marker_fp)
        self.assertEqual(sharding.check_before_push(DEFAULT_REPO_ID)[0], 409)

    def test_t2_f40_02_reject_failover_to_unhealthy_expired_non_replica_or_lagging_watermark_candidate(self) -> None:
        _, pulls, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        # Same as current primary
        self.assertEqual(sharding.execute_failover(ALICE, DEFAULT_REPO_ID, "shard-primary-1")[0], 409)
        # Not a configured replica
        sharding.upsert_node(ALICE, "shard-unassigned", "http://127.0.0.1:19199", role="replica", status="healthy", lease_expires_unix=5000)
        self.assertEqual(sharding.execute_failover(ALICE, DEFAULT_REPO_ID, "shard-unassigned")[0], 422)
        # Candidate replica lags repository storage_generation
        pulls.storage_generation = 3
        self.assertEqual(sharding.execute_failover(ALICE, DEFAULT_REPO_ID, "shard-replica-1")[0], 409)

    def test_t2_f40_03_reject_push_when_primary_node_lease_has_expired(self) -> None:
        _, _, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        # Primary lease_expires_unix is 5000; at now_unix=5001 push is rejected with 409
        err = sharding.check_before_push(DEFAULT_REPO_ID, now_unix=5001)
        self.assertIsNotNone(err)
        self.assertEqual(err[0], 409)
        self.assertIn("lease expired", err[1]["error"])

    def test_t2_f40_04_reject_exiting_degraded_readonly_mode_while_primary_node_is_offline_or_expired(self) -> None:
        _, _, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        sharding.set_degradation_drill(ALICE, DEFAULT_REPO_ID, degraded_readonly=True, now_unix=1000)
        sharding.patch_node(ALICE, "shard-primary-1", expected_version=1, status="offline")
        self.assertEqual(sharding.set_degradation_drill(ALICE, DEFAULT_REPO_ID, degraded_readonly=False, now_unix=1000)[0], 409)

    def test_t2_f40_05_reject_fence_token_regression_or_fencing_token_below_route_epoch(self) -> None:
        _, _, _, _, sharding = self.make_sharding_rig(seed_cluster=True)
        sharding.apply_or_verify_fence(ALICE, DEFAULT_REPO_ID, fenced_epoch=3, fencing_token=5)
