    def test_t3_11_f13_f14_f15_ci_pin_lease_coordination_blocks_premature_release_and_mirror_eviction(self) -> None:
        mfx = MirrorPinCheckoutFixture(self.tmp_path / "m_t3_11")
        c1, c2 = mfx.git.commits["c1"], mfx.git.commits["c2"]
        mfx.create_source_pin("job-live", c1)
        mfx.create_source_pin("job-old", c2)
        mfx.issue_checkout_lease("job-live", ttl_seconds=1800, now_unix=1000)
        mfx.issue_checkout_lease("job-old", cancelled=True, now_unix=1000)
        mfx.sync_mirror_snapshot("snap_1", mtime=1000.0)
        mfx.materialize_mirror_pin_and_job_view("snap_1", c1, create_job_view=True, mtime=1000.0)
        mfx.sync_mirror_snapshot("snap_2", mtime=2000.0)
        mfx.materialize_mirror_pin_and_job_view("snap_2", c2, create_job_view=True, mtime=2000.0)
        mfx.sync_mirror_snapshot("snap_3", mtime=3000.0)
        self.assertEqual(mfx.release_source_pin("job-live", now_unix=1100)[0], 409)
        self.assertEqual(mfx.release_source_pin("job-old", now_unix=1100)[0], 200)
        _, ev = mfx.evict_mirror(max_bytes=0, now_unix=1100)
        self.assertEqual((ev["evicted_pins"], ev["evicted_job_views"], ev["evicted_snapshots"]), (1, 1, 1))
        _, st = mfx.mirror_status(now_unix=1100)
        self.assertEqual((st["pin_count"], st["job_view_count"], st["active_lease_count"]), (1, 1, 1))

    def test_t3_12_f04_f06_f13_f14_ci_checkout_runs_check_merges_pr_and_evicts_old_generation(self) -> None:
        mfx = MirrorPinCheckoutFixture(self.tmp_path / "m_t3_12")
        pulls = Track1PullsEngine(mfx.git)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "CI isolated PR", "refs/heads/feature", "refs/heads/main")
        h1 = pr["head_oid"]
        mfx.create_source_pin("job-pr-1", h1)
        mfx.issue_checkout_lease("job-pr-1", ttl_seconds=600, now_unix=1000)
        mfx.sync_mirror_snapshot("snap_g1")
        paths = mfx.materialize_mirror_pin_and_job_view("snap_g1", h1, create_job_view=True)
        jv = paths["job_view"]
        # Job view has h1 but NOT unreachable c_div2
        self.assertEqual(subprocess.run(["git", f"--git-dir={jv}", "cat-file", "-e", h1], env=GIT_ENV, check=False).returncode, 0)
        self.assertNotEqual(subprocess.run(["git", f"--git-dir={jv}", "cat-file", "-e", mfx.git.commits["c_div2"]], env=GIT_ENV, check=False).returncode, 0)
        pulls.report_check(ALICE, DEFAULT_REPO_ID, h1, "ci/isolated", "completed", conclusion="success")
        self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 1, 1, h1, pr["base_oid"])[0], 200)
        mfx.conn.execute("UPDATE ci_checkout_jobs SET revoked=1 WHERE job_id='job-pr-1'")
        self.assertEqual(mfx.release_source_pin("job-pr-1", now_unix=1100)[0], 200)
        mfx.storage_generation = 2
        mfx.conn.execute("UPDATE repositories SET storage_generation=2 WHERE id=?", (mfx.repo_id,))
        mfx.sync_mirror_snapshot("snap_g2")
        _, ev = mfx.evict_mirror(prune_stale_generations=True)
        self.assertEqual((ev["evicted_pins"], ev["evicted_job_views"]), (1, 1))

