    def test_t3_17_f16_f17_f18_workspace_checkpoint_objects_verified_via_pando_graph_and_differential_export(self) -> None:
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "ws_t3_17")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "pando_t3_17")
        ws_repo = wfx.init_workspace("ws_pando", {"README.md": b"v1\n", "code.rs": b"pub fn run() {}\n"})
        (ws_repo / "code.rs").write_bytes(b"pub fn run() { println!(\"v2\"); }\n")
        subprocess.run(["git", "-C", str(ws_repo), "add", "-A"], env=GIT_ENV, check=True)
        subprocess.run(["git", "-C", str(ws_repo), "commit", "-m", "Commit v2"], stdout=subprocess.PIPE, env=GIT_ENV, check=True)
        head_oid = subprocess.run(["git", "-C", str(ws_repo), "rev-parse", "HEAD"], stdout=subprocess.PIPE, env=GIT_ENV, check=True).stdout.decode("ascii").strip()
        ckpt = wfx.create_checkpoint("ws_pando", "ckpt_pando")
        pack_bytes = subprocess.run(
            ["git", "-C", str(ws_repo), "pack-objects", "--stdout", "--revs"],
            input=f"{head_oid}\n".encode("ascii"),
            stdout=subprocess.PIPE,
            env=GIT_ENV,
            check=True,
        ).stdout
        p_path, _ = pando.register_manifest_pack("ws-pack", pack_bytes)
        diff = pando.diff_export_dual_operator(ws_repo / ".git", [p_path], want_oids=[head_oid])
        self.assertTrue(diff["parity"])
        manifest = wfx._load_verified_checkpoint(ckpt)
        self.assertIn("code.rs", manifest["entries"])

