    def test_t3_21_f01_f04_f05_f06_f22_f23_pr_webhook_loopback_delivery_and_signed_ci_callback_unlock_merge(self) -> None:
        _, pulls, webhooks, _ = self.make_webhooks_rig()
        secret = "t3-21-hmac-secret-key"
        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/webhook-gate"])
        with LoopbackWebhookReceiver(response_codes=[200, 200], secret=secret) as rx:
            _, hk = webhooks.create_webhook(
                ALICE, DEFAULT_REPO_ID, rx.url, secret, events=["pull_request", "push"], ci_contexts=["ci/webhook-gate"]
            )
            _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Webhook PR", "refs/heads/feature", "refs/heads/main")
            orch = webhooks.on_pull_synchronized(ALICE, DEFAULT_REPO_ID, pr)
            self.assertEqual(orch["seeded_checks"], ["ci/webhook-gate"])
            webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1000)
            self.assertEqual(len(rx.received), 1)
            self.assertTrue(rx.received[0]["signature_valid"])
            self.assertEqual(rx.received[0]["json"]["pull_number"], pr["number"])
            # Complete CI check via signed callback and merge PR
            cb_doc = {"commit_oid": pr["head_oid"], "context": "ci/webhook-gate", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2, "output": "OK"}
            cb_raw = json.dumps(cb_doc, sort_keys=True, separators=(",", ":")).encode("utf-8")
            self.assertEqual(webhooks.post_ci_callback(hk["id"], "cb-t3-21", webhooks.signature_header(secret, cb_raw), cb_doc)[0], 200)
            pulls.create_review(ALICE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])
            self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 200)
            # Outbox event from PR merge fans out push webhook
            self.assertEqual(webhooks.sync_outbox_events(), 1)
            webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1005)
            self.assertEqual(len(rx.received), 2)
            self.assertEqual(rx.received[1]["json"]["event"], "push")

