    def test_t3_23_f13_f14_f15_f23_auto_pr_ci_pin_protects_mirror_checkout_until_pr_merge_and_lease_revocation(self) -> None:
        _, pulls, webhooks, mfx = self.make_webhooks_rig(with_mirror=True)
        assert mfx is not None
        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_checks=["ci/mirror"])
        _, hk = webhooks.create_webhook(ALICE, DEFAULT_REPO_ID, "http://127.0.0.1:9303/ci", "mirror-pin-secret")
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Mirror Pin PR", "refs/heads/feature", "refs/heads/main")
        orch = webhooks.on_pull_synchronized(ALICE, DEFAULT_REPO_ID, pr)
        job_id = orch["ci_job_id"]
        mfx.issue_checkout_lease(job_id, ttl_seconds=1200, now_unix=1000)
        mfx.sync_mirror_snapshot("snap-1", mtime=1000.0)
        mfx.materialize_mirror_pin_and_job_view("snap-1", pr["head_oid"], create_job_view=True, mtime=1000.0)
        mfx.sync_mirror_snapshot("snap-2", mtime=2000.0)
        # Active lease prevents source pin release and mirror eviction
        self.assertEqual(mfx.release_source_pin(job_id, now_unix=1100)[0], 409)
        self.assertEqual(mfx.evict_mirror(max_bytes=0, now_unix=1100)[1]["evicted_pins"], 0)
        # Report check via webhook callback, merge PR, revoke lease, release pin, and evict
        cb_p = {"commit_oid": pr["head_oid"], "context": "ci/mirror", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2}
        cb_b = json.dumps(cb_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
        webhooks.post_ci_callback(hk["id"], "cb-mfx-1", webhooks.signature_header("mirror-pin-secret", cb_b), cb_p)
        self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 200)
        mfx.conn.execute("UPDATE ci_checkout_jobs SET revoked=1 WHERE job_id=?", (job_id,))
        self.assertEqual(mfx.release_source_pin(job_id, now_unix=1100)[0], 200)
        self.assertEqual(mfx.evict_mirror(max_bytes=0, now_unix=1100)[1]["evicted_pins"], 1)

