    def test_t3_26_f08_f10_f11_f12_f24_rbac_roles_enforced_across_browse_ref_transactions_and_lfs_gateway(self) -> None:
        git_fx, _, rbac = self.make_rbac_rig(with_browse_lfs=True)
        assert rbac.lfs is not None
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "bob", "read")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "charlie", "write")
        payload = b"rbac-lfs-binary-payload"
        oid = hashlib.sha256(payload).hexdigest()
        # Charlie (write) uploads LFS object and creates tag via ref-transaction
        self.assertEqual(rbac.lfs_batch(CHARLIE, DEFAULT_REPO_ID, "upload", [{"oid": oid, "size": len(payload)}])[0], 200)
        self.assertEqual(rbac.lfs.put_object(ALICE, DEFAULT_REPO_ID, oid, len(payload), [payload])[0], 200)
        self.assertEqual(rbac.post_ref_transaction(CHARLIE, DEFAULT_REPO_ID, 1, [{"ref_name": "refs/tags/v-rbac", "old_oid": ZERO_OID, "new_oid": git_fx.commits["c2"]}])[0], 200)
        # Bob (read) can download LFS batch and browse refs, but cannot run ref-transaction
        self.assertEqual(rbac.lfs_batch(BOB, DEFAULT_REPO_ID, "download", [{"oid": oid, "size": len(payload)}])[0], 200)
        self.assertEqual(rbac.browse_refs(BOB, DEFAULT_REPO_ID)[0], 200)
        self.assertEqual(rbac.post_ref_transaction(BOB, DEFAULT_REPO_ID, 1, [{"ref_name": "refs/tags/v-bob", "old_oid": ZERO_OID, "new_oid": git_fx.commits["c2"]}])[0], 403)

    def test_t3_27_f16_f17_f26_f27_pando_online_migration_delta_pack_push_and_rollback_to_gitfs_parity(self) -> None:
        git_fx = self.clone_git_fixture("t3_27.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "t3_27_store")
        mig = pando.migrate_full(git_fx.bare_dir)
        self.assertEqual(mig["storage_generation"], 2)
        # Push incremental OFS_DELTA pack to Pando after switchover
        stg = self.clone_git_fixture("t3_27_stg.git")
        b_big = stg.write_blob(("shared-prefix-line-\n" * 200).encode("utf-8") + b"pando-tail\n")
        t_big = stg.write_tree({"README.md": ("100644", b_big)})
        c_big = stg.commit_tree(t_big, [git_fx.commits["c2"]], "Pando delta commit")
        pack_b = stg.run_git(["pack-objects", "--stdout", "--revs", "--delta-base-offset"], input_bytes=f"{c_big}\n^{git_fx.commits['c2']}\n".encode("ascii")).stdout
        self.assertEqual(pando.pando_receive_pack("alice", [("refs/heads/main", git_fx.commits["c2"], c_big)], pack_bytes=pack_b, expected_storage_gen=2)[0], 200)
        rb = pando.rollback_to_gitfs(git_fx.bare_dir)
        self.assertEqual((rb["state"], rb["new_storage_generation"], rb["post_switchover_commits"]), ("ROLLED_BACK", 3, 1))
        self.assertEqual(git_fx.resolve_ref("refs/heads/main"), c_big)

