    def test_t3_29_f18_f28_f29_cross_node_dirty_snapshots_composed_into_multi_repo_virtual_namespace_and_git_view(self) -> None:
        node_a = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "t3_29_a")
        node_b = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "t3_29_b")
        node_coord = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "t3_29_coord")
        remote_cas = self.tmp_path / "t3_29_cas"

        ws_a = node_a.init_workspace("ws_a", {"api.rs": b"pub fn serve() {}\n", ".rootyardignore": b"*.log\n"})
        (ws_a / "api.rs").write_bytes(b"pub fn serve_v2() {}\n")
        (ws_a / "debug.log").write_bytes(b"ignored")
        pa = node_a.push_remote("ws_a", remote_cas, quiescent=True)

        ws_b = node_b.init_workspace("ws_b", {"client.ts": b"export const c = 1;\n"})
        (ws_b / "dirty_helper.ts").write_bytes(b"export const h = 2;\n")
        pb = node_b.push_remote("ws_b", remote_cas, quiescent=True)

        # Coordinator node pulls both remote checkpoints and mounts them into a unified virtual namespace
        node_coord.pull_remote(remote_cas, pa["checkpoint_id"], "ws_coord_a")
        node_coord.pull_remote(remote_cas, pb["checkpoint_id"], "ws_coord_b")
        ns = node_coord.namespace_mount(
            "ns-distributed",
            {"services/api": pa["checkpoint_id"], "clients/web": pb["checkpoint_id"]},
            revision=1,
        )
        self.assertEqual(ns["mount_count"], 2)
        gv = node_coord.namespace_git_view("ns-distributed")
        self.assertTrue(gv["fsck_passed"])
        v_repo = Path(gv["view_repo_path"])
        self.assertEqual((v_repo / "services/api/api.rs").read_bytes(), b"pub fn serve_v2() {}\n")
        self.assertEqual((v_repo / "clients/web/dirty_helper.ts").read_bytes(), b"export const h = 2;\n")
        self.assertFalse((v_repo / "services/api/debug.log").exists())

