    def test_t3_34_f22_f23_f24_f25_f33_f34_web_ui_pr_review_webhook_ci_callback_and_escaped_check_output(self) -> None:
        _, _, _, rbac, web = self.make_web_ui_rig(with_webhooks=True)
        assert rbac.webhooks is not None
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, BOB, "maintain")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, CHARLIE, "write")
        rbac.upsert_branch_rule(BOB, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/web-sec"], prevent_self_approval=True)
        secret = "web-ci-callback-secret-34"
        _, hk = rbac.create_webhook(BOB, DEFAULT_REPO_ID, "http://127.0.0.1:9434/ci", secret, events=["pull_request"], ci_contexts=["ci/web-sec"])

        st_pr, _, _, pr = web.create_pull_web(CHARLIE, DEFAULT_REPO_ID, "Web CI PR", "refs/heads/feature", "refs/heads/main")
        self.assertEqual(st_pr, 201)
        # Signed CI callback includes hostile HTML in check output -> rendered safely in Web UI
        cb_p = {
            "commit_oid": pr["head_oid"],
            "context": "ci/web-sec",
            "status": "completed",
            "conclusion": "success",
            "attempt": 1,
            "sequence": 2,
            "output": 'Passed <svg onload="alert(1)"> check with `0` warnings',
        }
        cb_b = json.dumps(cb_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
        self.assertEqual(rbac.webhooks.post_ci_callback(hk["id"], "ev-34-1", rbac.webhooks.signature_header(secret, cb_b), cb_p)[0], 200)

        st_ck, html_ck, _, _ = web.get_commit_checks_view(CHARLIE, DEFAULT_REPO_ID, pr["head_oid"])
        self.assertEqual(st_ck, 200)
        self.assertNotIn("<svg", html_ck.lower())
        self.assertIn("<code>0</code>", html_ck)

        web.create_review_web(BOB, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"], body="Approved via Web UI")
        st_mg, _, _, merged = web.merge_pull_web(BOB, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])
        self.assertEqual((st_mg, merged["state"]), (200, "merged"))

