    def test_t3_36_f26_f27_f35_f36_pando_online_migration_multi_pack_repack_s3_object_store_sync_and_rollback(self) -> None:
        git_fx = self.clone_git_fixture("t3_36.git")
        with LoopbackObjectStoreServer(self.tmp_path / "s3_t3_36") as srv:
            pando = PandoDeltaGraphExportFixture(self.tmp_path / "pando_t3_36")
            pando.configure_object_store(tier="s3_compatible", bucket="t3-36-bucket", endpoint_url=srv.url)
            pando.migrate_full(git_fx.bare_dir)
            r1 = pando.receive_incremental_commit("refs/heads/main", "f1.txt", b"commit 1\n", message="C1")
            r2 = pando.receive_incremental_commit("refs/heads/main", "f2.txt", b"commit 2\n", message="C2")
            self.assertEqual(len(pando.manifests), 3)

            rep = pando.repack(prune_superseded=True)
            self.assertEqual(rep["state"], "COMPLETED")
            self.assertEqual(len(pando.manifests), 1)
            self.assertTrue(pando.object_store_verify()["valid"])

            # Evict local compacted pack, hydrate it back from LoopbackObjectStoreServer, and rollback to GitFS
            new_pid = rep["new_pack_id"]
            (pando.objects_dir / f"{new_pid}.pack").unlink()
            (pando.objects_dir / f"{new_pid}.idx").unlink()
            pando.object_store_get(new_pid)
            rb = pando.rollback_to_gitfs(git_fx.bare_dir)
            self.assertEqual((rb["state"], git_fx.resolve_ref("refs/heads/main")), ("ROLLED_BACK", r2["commit_oid"]))
            self.assertNotEqual(r1["commit_oid"], r2["commit_oid"])

