    def test_t3_38_f18_f28_f37_f38_remote_cas_push_to_lazy_sparse_vfs_selective_hydration_cow_edit_and_evict(self) -> None:
        node_src = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "t3_38_src")
        node_vfs = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "t3_38_vfs")
        remote_cas = self.tmp_path / "t3_38_cas"

        node_src.init_workspace(
            "ws_src",
            {
                ".gitignore": b"*.tmp\n",
                "src/core.rs": b"pub fn v1() {}\n",
                "assets/weights.bin": b"W" * 16384,
                "docs/spec.md": b"# Spec\n",
            },
        )
        pushed = node_src.push_remote("ws_src", remote_cas, quiescent=True)
        mnt = node_vfs.vfs_mount("vfs-agent", pushed["checkpoint_id"], remote_cas_dir=remote_cas)
        # .gitignore is auto-hydrated; the 3 regular files remain dehydrated
        self.assertEqual(mnt["dehydrated_entries"], 3)
        node_vfs.vfs_hydrate("vfs-agent", ["src/core.rs", "docs/spec.md"], cow_write=True)
        mount_dir = Path(mnt["mount_path"])
        (mount_dir / "src/core.rs").write_bytes(b"pub fn v2_cow() {}\n")
        (mount_dir / "scratch.tmp").write_bytes(b"ignored scratch\n")

        st = node_vfs.vfs_status("vfs-agent")
        self.assertEqual(st["dehydrated"], ["assets/weights.bin"])
        self.assertEqual(st["hydrated_clean"], [".gitignore", "docs/spec.md"])
        self.assertEqual(st["modified"], ["src/core.rs"])
        self.assertEqual(st["ignored"], ["scratch.tmp"])

        ev = node_vfs.vfs_evict("vfs-agent", quiescent=True, skip_dirty=True)
        self.assertEqual(ev["evicted_paths"], ["docs/spec.md"])
        self.assertEqual((mount_dir / "src/core.rs").read_bytes(), b"pub fn v2_cow() {}\n")

