    def test_t3_40_f06_f10_f24_f39_f40_shard_routing_epoch_write_fencing_and_automated_failover_across_pr_merge_and_ref_tx(self) -> None:
        git_fx, pulls, browse, rbac, sharding = self.make_sharding_rig(seed_cluster=True)
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, BOB, "maintain")
        _, pr = rbac.create_pull(ALICE, DEFAULT_REPO_ID, "Sharded PR", "refs/heads/feature", "refs/heads/main")

        # Execute failover from shard-primary-1 to shard-replica-1 (bumps route_epoch=2, storage_generation=2)
        st_fo, fo = sharding.execute_failover(BOB, DEFAULT_REPO_ID, "shard-replica-1", now_unix=1000)
        self.assertEqual((st_fo, fo["new_storage_generation"]), (200, 2))

        # Stale storage_generation=1 on PR merge or ref-transaction is fenced with 409
        self.assertEqual(rbac.merge_pull(BOB, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"], storage_generation=1)[0], 409)
        self.assertEqual(
            browse.post_ref_transaction(
                ALICE,
                DEFAULT_REPO_ID,
                storage_generation=1,
                updates=[{"ref_name": "refs/tags/v-stale", "old_oid": ZERO_OID, "new_oid": git_fx.commits["c2"]}],
            )[0],
            409,
        )
        # Current storage_generation=2 succeeds on promoted primary
        self.assertEqual(rbac.merge_pull(BOB, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"], storage_generation=2)[0], 200)

    def test_t3_41_f33_f39_f40_web_ui_browse_survives_shard_degradation_drill_while_web_pr_merge_is_fenced(self) -> None:
        _, _, _, rbac, web = self.make_web_ui_rig(with_sharding=True)
