        sharding.upsert_node(ALICE, "shard-p1", "http://127.0.0.1:19301", role="primary", status="healthy", lease_expires_unix=5000)
        sharding.upsert_node(ALICE, "shard-r1", "http://127.0.0.1:19302", role="replica", status="healthy", lease_expires_unix=5000)
        sharding.configure_repo_route(ALICE, DEFAULT_REPO_ID, primary_node_id="shard-p1", read_replica_nodes=["shard-r1"])
        _, _, _, pr = web.create_pull_web(ALICE, DEFAULT_REPO_ID, "Drill PR", "refs/heads/feature", "refs/heads/main")

        # Enter degradation drill
        sharding.set_degradation_drill(ALICE, DEFAULT_REPO_ID, degraded_readonly=True, now_unix=1000)
        # Read-only Web UI overview and PR detail views still succeed (200) via replica read routing
        self.assertEqual(web.get_overview_view(ALICE, DEFAULT_REPO_ID)[0], 200)
        self.assertEqual(web.get_pull_detail_view(ALICE, DEFAULT_REPO_ID, pr["number"])[0], 200)
        # Web PR merge is fenced with 409 during degradation drill
        self.assertEqual(web.merge_pull_web(ALICE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 409)
        # Exit degradation drill -> Web PR merge succeeds
        sharding.set_degradation_drill(ALICE, DEFAULT_REPO_ID, degraded_readonly=False, now_unix=1000)
        self.assertEqual(web.merge_pull_web(ALICE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 200)

