class TestTier4RealWorldScenarios(BaseRootyardTestCase):
    """Tier 4: Real-World Application Scenarios (27 multi-step E2E scenarios S1-S27 across F1-F51)."""

    def test_t4_01_scenario_protected_mainline_pr_lifecycle_and_browse_verification(self) -> None:
        """S1: Protected Mainline Release Engineering (F1, F2, F3, F4, F5, F6, F8, F9)."""
        git_fx, pulls, browse = self.make_browse_rig()
        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/unit", "ci/sec"], require_fast_forward=True)
        _, pr = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Release feature", "refs/heads/feature", "refs/heads/main")
        _, diff1 = pulls.get_pull_diff(ALICE, DEFAULT_REPO_ID, pr["number"])
        self.assertTrue(diff1["fast_forward"])
        pulls.create_review(ALICE, DEFAULT_REPO_ID, 1, "changes_requested", pr["head_oid"], body="Needs security fix")
        pulls.report_check(ALICE, DEFAULT_REPO_ID, pr["head_oid"], "ci/unit", "completed", conclusion="success")
        pulls.report_check(ALICE, DEFAULT_REPO_ID, pr["head_oid"], "ci/sec", "completed", conclusion="failure")
        self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 1, 1, pr["head_oid"], pr["base_oid"])[0], 409)
        # Push fix commit to feature branch and refresh PR
        t_fix = git_fx.write_tree({"README.md": ("100644", b"# Rootyard\nSecurity fix applied.\n"), "src": ("040000", {"sec.rs": ("100644", b"pub fn verify() {}\n")})})
        h_fix = git_fx.commit_tree(t_fix, [pr["head_oid"]], "Apply security fix")
        git_fx.update_ref("refs/heads/feature", h_fix)
        _, pr_v2 = pulls.patch_pull(ALICE, DEFAULT_REPO_ID, 1, expected_version=1, head_oid=h_fix)
        self.assertEqual(pulls.count_valid_approvals(1, h_fix), 0)
        pulls.create_review(ALICE, DEFAULT_REPO_ID, 1, "approved", h_fix, body="Security verified")
        pulls.report_check(ALICE, DEFAULT_REPO_ID, h_fix, "ci/unit", "completed", conclusion="success", attempt=1, sequence=2)
        pulls.report_check(ALICE, DEFAULT_REPO_ID, h_fix, "ci/sec", "completed", conclusion="success", attempt=2, sequence=1)
        self.assertEqual(pulls.report_check(ALICE, DEFAULT_REPO_ID, h_fix, "ci/sec", "completed", conclusion="failure", attempt=1, sequence=9)[0], 409)
        st_m, merged = pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 1, pr_v2["version"], h_fix, pr["base_oid"], strategy="fast_forward")
        self.assertEqual(st_m, 200)
        self.assertEqual(merged["merge_commit_oid"], h_fix)
        _, refs = browse.get_refs(ALICE_RO, DEFAULT_REPO_ID)
        self.assertEqual(refs["head"]["oid"], h_fix)
        _, blob_sec = browse.get_blob(ALICE_RO, DEFAULT_REPO_ID, h_fix, path="src/sec.rs")
        self.assertEqual(blob_sec["content"], "pub fn verify() {}\n")

    def test_t4_02_scenario_large_media_lfs_pipeline_with_atomic_ref_release_and_backup(self) -> None:
        """S2: ML/Game Asset Git LFS Pipeline & Atomic Release (F8, F9, F10, F11, F12, F19)."""
        git_fx, _, browse = self.make_browse_rig()
        lfs = self.make_lfs_rig()
        shard1 = os.urandom(32768)
        shard2 = os.urandom(49152)
        oid1, oid2 = hashlib.sha256(shard1).hexdigest(), hashlib.sha256(shard2).hexdigest()
        st_b, batch_res, _ = lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": oid1, "size": len(shard1)}, {"oid": oid2, "size": len(shard2)}])
        self.assertEqual(st_b, 200)
        self.assertEqual(len(batch_res["objects"]), 2)
        # Corrupt upload attempt on shard1 fails and cleans .tmp
        self.assertEqual(lfs.put_object(ALICE, DEFAULT_REPO_ID, oid1, len(shard1), [b"corrupt" + shard1[7:]])[0], 422)
        self.assertEqual(list(lfs.repo_dir.glob(".tmp-*")), [])
        # Upload valid shards
        self.assertEqual(lfs.put_object(ALICE, DEFAULT_REPO_ID, oid1, len(shard1), [shard1[:16384], shard1[16384:]])[0], 200)
        self.assertEqual(lfs.put_object(ALICE, DEFAULT_REPO_ID, oid2, len(shard2), [shard2])[0], 200)
        self.assertEqual(lfs.post_verify(ALICE, DEFAULT_REPO_ID, oid1, len(shard1))[0], 200)
        # Deduplication check
        _, dedup_res, _ = lfs.post_batch(ALICE, DEFAULT_REPO_ID, "upload", [{"oid": oid1, "size": len(shard1)}])
        self.assertNotIn("actions", dedup_res["objects"][0])
        # Commit LFS pointer and atomically advance main + release branch + tag
        ptr1 = f"version https://git-lfs.github.com/spec/v1\noid sha256:{oid1}\nsize {len(shard1)}\n".encode("utf-8")
        t_rel = git_fx.write_tree({"models": ("040000", {"shard1.Pt": ("100644", ptr1)})})
        c_rel = git_fx.commit_tree(t_rel, [git_fx.commits["c2"]], "Release model v1.0.0")
        st_tx, _ = browse.post_ref_transaction(
            ALICE,
            DEFAULT_REPO_ID,
            1,
            [
                {"ref_name": "refs/heads/main", "old_oid": git_fx.commits["c2"], "new_oid": c_rel},
                {"ref_name": "refs/heads/release/v1", "old_oid": ZERO_OID, "new_oid": c_rel},
                {"ref_name": "refs/tags/v1.0.0-lfs", "old_oid": ZERO_OID, "new_oid": c_rel},
            ],
        )
        self.assertEqual(st_tx, 200)
        _, ptr_blob = browse.get_blob(ALICE_RO, DEFAULT_REPO_ID, c_rel, path="models/shard1.Pt")
        self.assertIn(oid1, ptr_blob["content"])
        _, dl_bytes, _ = lfs.get_object(ALICE_RO, DEFAULT_REPO_ID, oid1)
        self.assertEqual(dl_bytes, shard1)
        inv = lfs.verify_paired_backup()
        self.assertEqual(inv["ready_count"], 2)

    def test_t4_03_scenario_ci_farm_burst_checkout_watermark_eviction_and_pin_retirement(self) -> None:
        """S3: High-Throughput CI Farm Burst & Watermark Eviction (F13, F14, F15)."""
        mfx = MirrorPinCheckoutFixture(self.tmp_path / "s3_mirror")
        commits: list[str] = []
        parent = mfx.git.commits["c2"]
        for i in range(6):
            t = mfx.git.write_tree({f"ci_{i}.txt": ("100644", f"job {i}\n".encode("utf-8"))})
            c = mfx.git.commit_tree(t, [parent], f"CI commit {i}")
            commits.append(c)
            parent = c
            mfx.create_source_pin(f"job-{i}", c)
            mfx.sync_mirror_snapshot(f"snap-{i}", mtime=1000.0 + i * 100)
            mfx.materialize_mirror_pin_and_job_view(f"snap-{i}", c, create_job_view=True, mtime=1000.0 + i * 100)
        mfx.sync_mirror_snapshot("snap-current", mtime=3000.0)
        # 2 active, 1 cancelled, 1 revoked, 2 expired leases
        mfx.issue_checkout_lease("job-0", ttl_seconds=1800, now_unix=2000)
        mfx.issue_checkout_lease("job-1", ttl_seconds=1800, now_unix=2000)
        mfx.issue_checkout_lease("job-2", cancelled=True, now_unix=2000)
        mfx.issue_checkout_lease("job-3", revoked=True, now_unix=2000)
        mfx.issue_checkout_lease("job-4", ttl_seconds=10, now_unix=1900)
        mfx.issue_checkout_lease("job-5", ttl_seconds=10, now_unix=1900)
        self.assertEqual(mfx.release_source_pin("job-0", now_unix=2000)[0], 409)
        for j in ("job-2", "job-3", "job-4", "job-5"):
            self.assertEqual(mfx.release_source_pin(j, now_unix=2000)[0], 200)
        st_ev, ev = mfx.evict_mirror(max_bytes=0, now_unix=2000)
        self.assertEqual(st_ev, 200)
        self.assertEqual((ev["evicted_pins"], ev["evicted_job_views"], ev["evicted_snapshots"]), (4, 4, 4))
        _, st = mfx.mirror_status(now_unix=2000)
        self.assertEqual((st["pin_count"], st["job_view_count"], st["active_lease_count"]), (2, 2, 2))

    def test_t4_04_scenario_multi_agent_workspace_fork_dirty_sync_and_three_way_merge(self) -> None:
        """S4: Autonomous Multi-Agent Coding Swarm (F18)."""
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "s4_ws")
        wfx.init_workspace(
            "ws_base",
            {
                "src/lib.rs": b"pub mod core;\n",
                "README.md": b"# Swarm\n",
                ".gitignore": b"target/\n",
                ".rootyardignore": b"*.scratch\n",
            },
        )
        ckpt0 = wfx.create_checkpoint("ws_base", "ckpt-0")
        ra = wfx.restore_workspace(ckpt0, "ws-agent-a")
        rb = wfx.restore_workspace(ckpt0, "ws-agent-b")
        rc = wfx.restore_workspace(ckpt0, "ws-conflict")
        (ra / "src/agent_a.rs").write_bytes(b"pub fn a() {}\n")
        (ra / "temp.scratch").write_bytes(b"scratch")
        (rb / "src/agent_b.rs").write_bytes(b"pub fn b() {}\n")
        ckpt_a = wfx.create_checkpoint("ws-agent-a", "ckpt-a")
        cs_a = wfx.create_changeset(ckpt0, ckpt_a, "cs-a")
        wfx.apply_changeset("ws-agent-b", cs_a, quiescent=True)
        self.assertTrue((rb / "src/agent_a.rs").is_file())
        self.assertTrue((rb / "src/agent_b.rs").is_file())
        self.assertFalse((rb / "temp.scratch").exists())
        # Conflicting workspace edit
        (rc / "src/agent_a.rs").write_bytes(b"pub fn conflicting_a() {}\n")
        with self.assertRaisesRegex(ValueError, "3-way apply conflict"):
            wfx.apply_changeset("ws-conflict", cs_a, quiescent=True)
        ckpt_b = wfx.create_checkpoint("ws-agent-b", "ckpt-b")
        v_dir = wfx.project_readonly_view(ckpt_b)
        self.assertTrue(wfx.verify_readonly_view(ckpt_b, v_dir)["valid"])

    def test_t4_05_scenario_pando_incremental_pack_pipeline_differential_git_audit_and_gc(self) -> None:
        """S5: Pando Cloud-Native Object Store Pipeline (F16, F17)."""
        git_fx = self.clone_git_fixture("s5_pando.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "s5_store")
        m1 = git_fx.commits["c2"]
        base_blob = ("pando-cloud-line-\n" * 300).encode("utf-8")
        b_m2 = git_fx.write_blob(base_blob + b"gen2-delta\n")
        t_m2 = git_fx.write_tree({"cloud.txt": ("100644", b_m2)})
        m2 = git_fx.commit_tree(t_m2, [m1], "Generation 2 commit")
        p1_bytes = git_fx.run_git(["pack-objects", "--stdout", "--revs"], input_bytes=f"{m1}\n".encode("ascii")).stdout
        p2_bytes = git_fx.run_git(["pack-objects", "--stdout", "--revs", "--no-reuse-delta"], input_bytes=f"{m2}\n^{m1}\n".encode("ascii")).stdout
        p1_path, _ = pando.register_manifest_pack("pack-m1", p1_bytes)
        p2_path, _ = pando.register_manifest_pack("pack-m2", p2_bytes)
        (pando.objects_dir / "pack-aborted.pack").write_bytes(b"aborted")
        pando.snapshots = [{"id": "snap-exp", "expires_at": 500.0}, {"id": "snap-ok", "expires_at": 5000.0}]
        pando.generation = 2
        pando.refs = {"refs/heads/main": m2}
        pando.operations["op-2"] = {"id": "op-2", "repository_id": DEFAULT_REPO_ID, "state": "COMMITTED"}
        self.assertEqual(pando.http_get_refs(DEFAULT_REPO_ID, "alice")[1]["refs"]["refs/heads/main"], m2)
        diff_res = pando.diff_export_dual_operator(git_fx.bare_dir, [p1_path, p2_path], want_oids=[m2], have_oids=(m1,))
        self.assertTrue(diff_res["parity"])
        gc_res = pando.pando_gc(now_ts=1000.0)
        self.assertEqual((gc_res["reclaimed_packs"], gc_res["expired_snapshots"]), (1, 1))

