    def test_t4_07_scenario_concurrent_release_train_cas_collision_recovery_and_browse_audit(self) -> None:
        """S7: Concurrent Release Train CAS Collision & Recovery (F1, F3, F4, F5, F6, F8, F9, F10)."""
        git_fx, pulls, browse = self.make_browse_rig()
        pulls.upsert_branch_rule(ALICE, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/train"], require_fast_forward=False)
        b0 = git_fx.commits["c2"]
        _, pr1 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Train PR 1", "refs/heads/feature", "refs/heads/main")
        _, pr2 = pulls.create_pull(ALICE, DEFAULT_REPO_ID, "Train PR 2", "refs/heads/diverged", "refs/heads/main")
        for num, h_oid in ((1, pr1["head_oid"]), (2, pr2["head_oid"])):
            pulls.create_review(ALICE, DEFAULT_REPO_ID, num, "approved", h_oid)
            pulls.report_check(ALICE, DEFAULT_REPO_ID, h_oid, "ci/train", "completed", conclusion="success")
        st1, m1_resp = pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 1, 1, pr1["head_oid"], b0, strategy="fast_forward")
        self.assertEqual(st1, 200)
        m1 = m1_resp["merge_commit_oid"]
        # PR 2 with stale base_oid=b0 fails with 409
        self.assertEqual(pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 2, 1, pr2["head_oid"], b0, strategy="merge_commit")[0], 409)
        # Concurrent ref-transaction with stale old_oid=b0 fails, then succeeds with old_oid=m1
        self.assertEqual(browse.post_ref_transaction(ALICE, DEFAULT_REPO_ID, 1, [{"ref_name": "refs/heads/main", "old_oid": b0, "new_oid": m1}])[0], 409)
        self.assertEqual(browse.post_ref_transaction(ALICE, DEFAULT_REPO_ID, 1, [{"ref_name": "refs/tags/v1.1-pre", "old_oid": ZERO_OID, "new_oid": m1}])[0], 200)
        # Refresh PR 2 base_oid to m1 and merge via merge_commit
        pulls.patch_pull(ALICE, DEFAULT_REPO_ID, 2, expected_version=1, base_oid=m1)
        st2, m2_resp = pulls.merge_pull(ALICE, DEFAULT_REPO_ID, 2, 2, pr2["head_oid"], m1, strategy="merge_commit")
        self.assertEqual(st2, 200)
        _, commits_list = browse.get_commits(ALICE_RO, DEFAULT_REPO_ID, oid="refs/heads/main", limit=5)
        self.assertEqual(commits_list["items"][0]["oid"], m2_resp["merge_commit_oid"])

    def test_t4_08_scenario_workspace_agent_develops_lfs_backed_feature_through_pr_and_pando_audit(self) -> None:
        """S8: AI Workspace Agent -> LFS Asset + PR Merge -> Pando Differential Audit (F1, F3, F4, F6, F9, F11, F12, F16, F17, F18)."""
        git_fx, pulls, browse = self.make_browse_rig()
        lfs = self.make_lfs_rig()
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "s8_ws")
