    def test_t4_11_scenario_enterprise_multi_team_pr_governance_with_webhook_ci_and_audit_trail(self) -> None:
        """S11: Enterprise Multi-Team PR Governance + Loopback Webhook CI + Audit Trail (F1, F3, F4, F5, F6, F22, F23, F24, F25)."""
        _, _, rbac = self.make_rbac_rig(with_webhooks=True, with_browse_lfs=True)
        assert rbac.webhooks is not None and rbac.browse is not None
        # 1. Owner ALICE provisions security team (maintain), platform team (write), and QA collaborator (triage)
        rbac.create_team(ALICE, DEFAULT_REPO_ID, "sec-maintainers", "Security Maintainers", "maintain", now_unix=100)
        rbac.add_team_member(ALICE, DEFAULT_REPO_ID, "sec-maintainers", "bob", now_unix=110)
        rbac.create_team(ALICE, DEFAULT_REPO_ID, "platform-devs", "Platform Devs", "write", now_unix=120)
        rbac.add_team_member(ALICE, DEFAULT_REPO_ID, "platform-devs", "charlie", now_unix=130)
        rbac.add_team_member(ALICE, DEFAULT_REPO_ID, "platform-devs", "dave", now_unix=140)
        # 2. Maintainer BOB configures branch protection (2 approvals, prevent_self_approval, required ci/sec-scan) and webhook
        rbac.upsert_branch_rule(
            BOB, DEFAULT_REPO_ID, "main", required_approvals=2, required_checks=["ci/sec-scan"], prevent_self_approval=True, now_unix=150
        )
        secret = "s11-enterprise-webhook-secret"
        with LoopbackWebhookReceiver(response_codes=[503, 200, 200], secret=secret) as rx:
            _, hk = rbac.create_webhook(
                BOB, DEFAULT_REPO_ID, rx.url, secret, events=["pull_request", "push"], ci_contexts=["ci/sec-scan"], now_unix=160
            )
            # 3. Developer CHARLIE opens PR -> auto-pins head_oid and enqueues pull_request webhook
            _, pr = rbac.create_pull(CHARLIE, DEFAULT_REPO_ID, "Enterprise Feature", "refs/heads/feature", "refs/heads/main", now_unix=170)
            # First delivery attempt hits 503, second attempt succeeds with 200
            rbac.webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1000, base_backoff_sec=2)
            rbac.webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1002, base_backoff_sec=2)
            self.assertEqual(len(rx.received), 2)
            self.assertTrue(rx.received[-1]["signature_valid"])
            # 4. CHARLIE cannot self-approve; BOB and DAVE submit distinct write+ approvals
            self.assertEqual(rbac.create_review(CHARLIE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])[0], 403)
            rbac.create_review(BOB, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"], now_unix=180)
            rbac.create_review(DAVE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"], now_unix=190)
            # 5. External CI posts signed callback -> unlocks merge -> push webhook delivered
            cb_p = {"commit_oid": pr["head_oid"], "context": "ci/sec-scan", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2}
            cb_b = json.dumps(cb_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
            self.assertEqual(rbac.webhooks.post_ci_callback(hk["id"], "s11-cb-1", rbac.webhooks.signature_header(secret, cb_b), cb_p)[0], 200)
            self.assertEqual(rbac.merge_pull(BOB, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"], now_unix=200)[0], 200)
            rbac.webhooks.sync_outbox_events()
            rbac.webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1010)
            self.assertEqual(rx.received[-1]["json"]["event"], "push")
            # 6. Audit log pagination verifies complete governance history
            _, audit_p1 = rbac.list_audit_log(BOB, DEFAULT_REPO_ID, after=0, limit=5)
            _, audit_p2 = rbac.list_audit_log(BOB, DEFAULT_REPO_ID, after=audit_p1["next_after"], limit=10)
            self.assertGreaterEqual(len(audit_p1["items"]) + len(audit_p2["items"]), 9)

    def test_t4_12_scenario_zero_downtime_gitfs_to_pando_cutover_live_writes_and_emergency_rollback(self) -> None:
        """S12: Zero-Downtime GitFS -> Pando Online Cutover, Post-Switchover Traffic & Emergency Rollback (F16, F17, F26, F27)."""
        git_fx = self.clone_git_fixture("s12_cutover.git")
        pando = PandoDeltaGraphExportFixture(self.tmp_path / "s12_pando")
        # 1. Copy & verify while repository is still serving GitFS
        pando.migrate_step(git_fx.bare_dir, "copy")
        pando.migrate_step(git_fx.bare_dir, "verify")
        # 2. Drain, fence (storage_generation 1 -> 2), and switchover to Pando
        pando.migrate_step(git_fx.bare_dir, "drain")
        pando.migrate_step(git_fx.bare_dir, "fence")
        sw = pando.migrate_step(git_fx.bare_dir, "switchover")
        self.assertEqual((sw["storage_backend"], sw["storage_generation"]), ("pando", 2))
        # 3. Serve live Pando writes (2 new commits + 1 new branch) while GitFS rejects writes
        self.assertEqual(pando.gitfs_push_commit(git_fx.bare_dir, "refs/heads/main", git_fx.commits["c2"], git_fx.commits["c3"])[0], 409)
        stg = self.clone_git_fixture("s12_stg.git")
        t1 = stg.write_tree({"s12_1.txt": ("100644", b"pando commit 1\n")})
        c_p1 = stg.commit_tree(t1, [git_fx.commits["c2"]], "Pando commit 1")
        t2 = stg.write_tree({"s12_1.txt": ("100644", b"pando commit 1\n"), "s12_2.txt": ("100644", b"pando commit 2\n")})
        c_p2 = stg.commit_tree(t2, [c_p1], "Pando commit 2")
        pack_p = stg.run_git(["pack-objects", "--stdout", "--revs", "--delta-base-offset"], input_bytes=f"{c_p2}\n^{git_fx.commits['c2']}\n".encode("ascii")).stdout
        self.assertEqual(
            pando.pando_receive_pack(
                "alice",
                [("refs/heads/main", git_fx.commits["c2"], c_p2), ("refs/heads/pando-live", ZERO_OID, c_p2)],
                pack_bytes=pack_p,
                expected_storage_gen=2,
            )[0],
            200,
        )
        # 4. Execute emergency rollback to GitFS (storage_generation 2 -> 3) with zero data loss
        rb = pando.rollback_to_gitfs(git_fx.bare_dir)
        self.assertEqual((rb["state"], rb["new_storage_generation"], rb["post_switchover_commits"]), ("ROLLED_BACK", 3, 2))
        self.assertEqual(git_fx.resolve_ref("refs/heads/main"), c_p2)
        self.assertEqual(git_fx.resolve_ref("refs/heads/pando-live"), c_p2)
        # 5. GitFS accepts post-rollback commit
        t3 = stg.write_tree({"s12_3.txt": ("100644", b"gitfs post-rollback\n")})
        c_g3 = stg.commit_tree(t3, [c_p2], "GitFS commit 3")
        pack_g3 = stg.run_git(["pack-objects", "--stdout", "--revs"], input_bytes=f"{c_g3}\n^{c_p2}\n".encode("ascii")).stdout
        git_fx.run_git(["index-pack", "--stdin", "--strict"], input_bytes=pack_g3)
        self.assertEqual(pando.gitfs_push_commit(git_fx.bare_dir, "refs/heads/main", c_p2, c_g3)[0], 200)

