    def test_t4_14_scenario_full_devsecops_ci_mirror_webhook_dead_letter_recovery_and_rbac_merge(self) -> None:
        """S14: Webhook Dead-Letter Recovery + CI Mirror Pin + Multi-Reviewer RBAC Merge (F13, F14, F15, F22, F23, F24, F25)."""
        mfx = MirrorPinCheckoutFixture(self.tmp_path / "s14_mirror")
        pulls = Track1PullsEngine(mfx.git)
        webhooks = TrackAWebhooksEngine(pulls, mirror_fx=mfx)
        rbac = TrackBMembersRbacAuditEngine(pulls, webhooks_engine=webhooks)

        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "bob", "maintain")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, "charlie", "write")
        rbac.upsert_branch_rule(BOB, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/e2e"], prevent_self_approval=True)

        secret = "s14-dead-letter-secret"
        with LoopbackWebhookReceiver(response_codes=[500, 502, 200], secret=secret) as rx:
            _, hk = rbac.create_webhook(BOB, DEFAULT_REPO_ID, rx.url, secret, events=["pull_request"], ci_contexts=["ci/e2e"])
            # Lower max_attempts to 2 on the enqueued delivery by creating PR and dispatching twice (500, 502 -> dead_letter)
            _, pr = rbac.create_pull(CHARLIE, DEFAULT_REPO_ID, "Resilient PR", "refs/heads/feature", "refs/heads/main")
            delivs = webhooks.list_deliveries(ALICE, DEFAULT_REPO_ID, hk["id"])[1]["items"]
            deliv_id = delivs[0]["id"]
            webhooks.conn.execute("UPDATE forge_webhook_deliveries SET max_attempts=2 WHERE id=?", (deliv_id,))
            webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1000, base_backoff_sec=1)
            d_dead = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1001, base_backoff_sec=1)[1]["items"][0]
            self.assertEqual(d_dead["state"], "dead_letter")
            # Operator retries dead-letter delivery -> 3rd attempt hits 200 OK
            webhooks.retry_delivery(ALICE, DEFAULT_REPO_ID, hk["id"], deliv_id, now_unix=1005)
            d_ok = webhooks.dispatch_due_deliveries(ALICE, DEFAULT_REPO_ID, now_unix=1005)[1]["items"][0]
            self.assertEqual(d_ok["state"], "delivered")
            # Signed CI callback + BOB approval -> merge succeeds
            cb_p = {"commit_oid": pr["head_oid"], "context": "ci/e2e", "status": "completed", "conclusion": "success", "attempt": 1, "sequence": 2}
            cb_b = json.dumps(cb_p, sort_keys=True, separators=(",", ":")).encode("utf-8")
            webhooks.post_ci_callback(hk["id"], "s14-cb-ok", webhooks.signature_header(secret, cb_b), cb_p)
            rbac.create_review(BOB, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])
            self.assertEqual(rbac.merge_pull(BOB, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])[0], 200)

