    def test_t4_17_scenario_browser_first_team_triage_xss_defense_pr_review_and_merge_via_html_web_ui(self) -> None:
        """S17: Browser-First Team Issue Triage, XSS Defense, PR Review & Merge via Server-Side HTML Web UI (F24, F25, F32, F33, F34)."""
        git_fx, pulls, _, rbac, web = self.make_web_ui_rig()
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, BOB, "triage")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, CHARLIE, "write")
        rbac.upsert_collaborator(ALICE, DEFAULT_REPO_ID, DAVE, "maintain")
        rbac.upsert_branch_rule(DAVE, DEFAULT_REPO_ID, "main", required_approvals=1, required_checks=["ci/ui"], prevent_self_approval=True)

        # 1. Triage collaborator BOB files an issue containing hostile XSS payloads
        st_iss, html_iss, hdr_iss, iss = web.create_issue_web(
            BOB,
            DEFAULT_REPO_ID,
            'Bug in <script>alert("title")</script> parser',
            body='Reproduction: [exploit](&#106;avascript:alert(1)) <svg onload=alert(2)> `cargo test`',
        )
        self.assertEqual(st_iss, 201)
        self.assertIn("default-src 'none'", hdr_iss["Content-Security-Policy"])
        self.assertNotIn("<script>", html_iss)
        self.assertNotIn("<svg", html_iss.lower())
        self.assertIn("<code>cargo test</code>", html_iss)

        # 2. Write collaborator CHARLIE opens a PR via Web UI, DAVE reviews and approves, CI reports check, DAVE merges via Web UI
        st_pr, _, _, pr = web.create_pull_web(CHARLIE, DEFAULT_REPO_ID, f"Fix issue #{iss['number']}", "refs/heads/feature", "refs/heads/main")
        self.assertEqual(st_pr, 201)
        self.assertEqual(web.create_review_web(CHARLIE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"])[0], 403)
        web.create_review_web(DAVE, DEFAULT_REPO_ID, pr["number"], "approved", pr["head_oid"], body="Verified fix")
        pulls.report_check(ALICE, DEFAULT_REPO_ID, pr["head_oid"], "ci/ui", "completed", conclusion="success")
        st_mg, html_mg, _, _ = web.merge_pull_web(DAVE, DEFAULT_REPO_ID, pr["number"], 1, pr["head_oid"], pr["base_oid"])
        self.assertEqual(st_mg, 200)
        self.assertIn('data-state="merged"', html_mg)

        # 3. Close issue and verify Web UI audit log view
        web.update_issue_web(BOB, DEFAULT_REPO_ID, iss["number"], expected_version=1, state="closed")
        st_au, html_au, _, meta_au = web.get_audit_view(DAVE, DEFAULT_REPO_ID)
        self.assertEqual(st_au, 200)
        self.assertIn("pull.merged", html_au)
        self.assertGreaterEqual(len(meta_au["items"]), 6)
        self.assertEqual(git_fx.resolve_ref("refs/heads/main"), pr["head_oid"])

    def test_t4_18_scenario_cloud_native_pando_s3_object_store_cutover_multi_pack_repack_and_disaster_recovery(self) -> None:
        """S18: Cloud-Native Pando S3 Object-Store Cutover, Multi-Pack Compaction, Eviction Hydration & Rollback (F16, F17, F26, F27, F35, F36)."""
        git_fx, pulls, browse = self.make_browse_rig("s18_pando.git")
        with LoopbackObjectStoreServer(self.tmp_path / "s18_s3_srv") as srv:
            pando = PandoDeltaGraphExportFixture(self.tmp_path / "s18_pando_store")
            pando.configure_object_store(tier="s3_compatible", bucket="s18-prod-cas", endpoint_url=srv.url)
            browse.pando = pando

            # 1. Online migrate GitFS -> Pando and push 2 incremental commits + 1 orphan pack
            pando.migrate_full(git_fx.bare_dir)
            pulls.storage_generation = pando.storage_generation
            pando.receive_incremental_commit("refs/heads/main", "cloud1.rs", b"pub fn c1() {}\n", message="Cloud 1")
            c_final = pando.receive_incremental_commit("refs/heads/main", "cloud2.rs", b"pub fn c2() {}\n", message="Cloud 2")
            orphan_b = pando.build_pack_from_entries([(3, b"orphan data\n", None, None)])
            pando.register_manifest_pack("pack-s18-orphan", orphan_b, b"idx-orphan")
            self.assertEqual(len(pando.manifests), 4)

            # 2. Compact all 4 packs into 1 deterministic pack and sync to LoopbackObjectStoreServer
            rep = pando.repack(prune_superseded=True)
            self.assertEqual(rep["compacted_packs"], 4)
            self.assertEqual(len(pando.manifests), 1)
            self.assertTrue(pando.object_store_verify()["valid"])

            # 3. Simulate local disk loss of compacted pack, hydrate from S3 loopback server, and verify gateway + rollback
            pid = rep["new_pack_id"]
            (pando.objects_dir / f"{pid}.pack").unlink()
            (pando.objects_dir / f"{pid}.idx").unlink()
            pando.object_store_get(pid)
            self.assertEqual(browse.get_storage_route(ALICE, DEFAULT_REPO_ID, operation="write")[1]["storage_backend"], "pando")
            rb = pando.rollback_to_gitfs(git_fx.bare_dir)
            self.assertEqual((rb["state"], git_fx.resolve_ref("refs/heads/main")), ("ROLLED_BACK", c_final["commit_oid"]))

    def test_t4_19_scenario_autonomous_agent_fleet_on_lazy_sparse_vfs_with_cow_checkpoints_eviction_and_namespace_view(self) -> None:
        """S19: Autonomous Agent Fleet on Lazy Sparse VFS with CoW Edits, Clean Eviction & Virtual Namespace Git View (F18, F28, F29, F37, F38)."""
        wfx = WorkspaceManifestIgnoreViewFixture(self.tmp_path / "s19_ws")
