        (m1_dir / "agent1.log").write_bytes(b"ignored log\n")
        # Evict clean hydrated billing file while keeping dirty auth file
        ev = wfx.vfs_evict("vfs-agent-1", quiescent=True, skip_dirty=True)
        self.assertEqual(ev["evicted_paths"], ["services/billing/lib.rs"])

        ckpt_v2 = wfx.vfs_checkpoint("vfs-agent-1", "ckpt-s19-v2")
