def _matches_feature(method_name: str, feature_arg: Optional[str]) -> bool:
    if feature_arg is None:
        return True
    norm = feature_arg.strip().upper()
    if not re.match(r"^F([1-9]|[1-4][0-9]|5[0-1])$", norm):
        return False
    f_num = int(norm[1:])
    f_tag = f"f{f_num:02d}"
    if method_name.startswith(f"test_t1_{f_tag}_") or method_name.startswith(f"test_t2_{f_tag}_"):
        return True
    if method_name.startswith("test_t3_") and f"_{f_tag}_" in method_name:
        return True
    prefixes = FEATURE_TO_TIER3_AND_TIER4.get(norm, ())
    return any(method_name.startswith(p) for p in prefixes)


def build_suite(tier: str = "all", feature: Optional[str] = None) -> unittest.TestSuite:
    tier_map = {
        "1": [TestTier1FeatureCoverage],
        "2": [TestTier2BoundaryAndCornerCases],
        "3": [TestTier3CrossFeatureCombinations],
        "4": [TestTier4RealWorldScenarios],
        "all": [
            TestTier1FeatureCoverage,
            TestTier2BoundaryAndCornerCases,
            TestTier3CrossFeatureCombinations,
            TestTier4RealWorldScenarios,
        ],
    }
    suite = unittest.TestSuite()
    for cls in tier_map[tier]:
        for name in sorted(dir(cls)):
            if name.startswith("test_") and _matches_feature(name, feature):
                suite.addTest(cls(name))
    return suite


def main(argv: Optional[list[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Rootyard 4-Tier Requirement-Driven E2E Test Suite (F1-F51)")
    parser.add_argument("--tier", choices=("1", "2", "3", "4", "all"), default="all", help="Test tier to execute")
    parser.add_argument("--feature", default=None, help="Filter by feature ID (F1..F51)")
    parser.add_argument("--report", default=None, help="Optional path to write JSON test report")
    parser.add_argument("--binary", default="target/debug/rootyard", help="Required native service binary")
    parser.add_argument("--reference-only", action="store_true", help="Run Python reference models; not native acceptance evidence")
    parser.add_argument("-v", "--verbose", action="store_true", help="Verbose test output")
    args = parser.parse_args(argv)

    if not args.reference_only:
        from native_tiers import run
        return run(args)

    suite = build_suite(tier=args.tier, feature=args.feature)
    total_scheduled = suite.countTestCases()
    if total_scheduled == 0:
        print(f"ERROR: 0 tests matched --tier={args.tier} --feature={args.feature}", file=sys.stderr)
        return 1

    runner = unittest.TextTestRunner(verbosity=2 if args.verbose else 1)
    result = runner.run(suite)

    passed = result.testsRun - len(result.failures) - len(result.errors) - len(result.skipped)
    summary = {
        "backend": "reference_model",
        "production_acceptance": False,
        "tier": args.tier,
        "feature": args.feature,
        "total": result.testsRun,
        "passed": passed,
        "failed": len(result.failures),
        "errors": len(result.errors),
        "skipped": len(result.skipped),
        "success": result.wasSuccessful() and len(result.skipped) == 0 and result.testsRun == total_scheduled,
    }
    print(
        f"SUMMARY: tier={args.tier} total={summary['total']} passed={summary['passed']} "
        f"failed={summary['failed']} errors={summary['errors']} skipped={summary['skipped']}"
    )
    if args.report:
        report_path = Path(args.report)
        report_path.parent.mkdir(parents=True, exist_ok=True)
        report_path.write_text(json.dumps(summary, indent=2) + "\n", encoding="utf-8")

    return 0 if summary["success"] else 1


if __name__ == "__main__":
    sys.exit(main())

